\label{asympcomplhardy}
  Let $d\in\mathbb{N}$, $0<\alpha\in(0,d)\cap(0,2]$, and $\kappa\leq\kappa_{\rm c}$.
  \begin{enumerate}
  \item Let $\alpha>1$, $\tilde\kappa\leq\kappa$, and $V_\kappa:\mathbb{R}^d\to\mathbb{R}$ be such that
    $$
    \frac{\tilde\kappa}{|x|^\alpha} \leq V_\kappa(x) \leq \frac{\kappa}{|x|^\alpha}, \quad x\in \mathbb{R}^d.
    $$
    Then the wave operator $W(L_0-V_\kappa,L_0)$ is asymptotically complete.

  \item Let $\alpha\leq1$ and $\kappa\neq0$. Then $W(L_\kappa,L_0)$ does not exist.
  \end{enumerate}

\label{mizutaniyaoconditions}
  The function $V:\mathbb{R}^d\to\mathbb{R}$ is such that for all $j=0,1,2$, we have $V_j(x):=(-x\cdot\nabla)^j V \in L_{\rm loc}^1(\mathbb{R}^d)$ and the estimates
  \begin{align}
    \label{eq:mizutaniyaocond1}
    \| |(x\cdot\nabla)^j V|^{1/2}(L_0+1)^{-1/2}\| & \lesssim 1, \quad j=0,1,2, \\
    \label{eq:mizutaniyaocond2}
    \langle u,(L_0-V)u\rangle & \gtrsim \langle u,L_0 u\rangle, \\
    \label{eq:mizutaniyaocond3}
    \langle u,(\alpha L_0-V_1)u\rangle & \gtrsim \langle u,L_0 u\rangle, \\
    \label{eq:mizutaniyaocond4}
    |\langle u,(\alpha^2 L_0-V_2)u\rangle| & \lesssim \langle u,(\alpha L_0 - V_1) u\rangle
  \end{align}
  hold for all $u\in C_c^\infty(\mathbb{R}^d)$.

\label{asympcomplhardyplusperturbation}
  Let $d\in\mathbb{N}$, $\alpha\in(0,d)\cap(0,2]$, $\kappa\leq\kappa_{\rm c}$, and $\sigma=\Phi^{-1}(\kappa)\in(-M,(d-\alpha)/2]$.
  Then, the following statements hold.
  \begin{enumerate}
  \item \label{asympcomplhardyplusperturbation:acshortrange}
    Assume in addition $\alpha>1$. Let $\tilde\kappa\leq\kappa$ and $V_\kappa:\mathbb{R}^d\to\mathbb{R}$ be such that
    $$
    \frac{\tilde\kappa}{|x|^\alpha} \leq V_\kappa(x) \leq \frac{\kappa}{|x|^\alpha}, \quad x\in \mathbb{R}^d.
    $$
    Assume also $V^S$ satisfies \eqref{eq:basicassumpshortrange} for some $\rho_S>1$.
    Then $W(L_0 - V_\kappa - V^S, L_0)$ and $W(L_0 - V_\kappa - V^S,L_0-V_\kappa)$ are asymptotically complete.


  \item \label{asympcomplhardyplusperturbation:acshortrangesmallalpha}
    Assume in addition $\alpha\leq1$ and one of the following assumptions:
    \begin{enumerate}
    \item[(a)] Assume $d\geq2$, $\alpha>1/3$, $\rho_S>\max\{1,2\alpha\}$.
      Assume $V^S$ satisfies \eqref{eq:basicassumpshortrange}, that $\kappa/|x|^\alpha+V^S(x)$ obeys Assumption~\ref{mizutaniyaoconditions}, and that there are $\tilde\kappa\leq\kappa'<\kappa_{\rm c}$ such that
      \begin{align}
        \label{ass6}
        \frac{\tilde\kappa}{|x|^\alpha}
        \leq \frac{\kappa}{|x|^\alpha} + V^S(x)
        \leq \frac{\kappa'}{|x|^\alpha}.
      \end{align}
      Let $\sigma'=\Phi^{-1}(\kappa')\in(-M,(d-\alpha)/2)$. If $1/3<\alpha<1/2$, assume in addition that $\sigma'<(d+\alpha-1)/2$.

    \item[(b)] Assume $\alpha>1/2$, $\sigma<(d-1)/2$, $\rho_S>1$, and $V^S\in C^\infty(\mathbb{R}^d)$ satisfies~\eqref{ass5} for some $\rho_S>1$ and all multi-indices $\beta$.
    \end{enumerate}
    Then $W(L_\kappa - V^S,L_\kappa)$ is asymptotically complete.
  \end{enumerate}

\label{lem:MY-sufficient}
  Let $d\in\mathbb{N}$, $\alpha\in(0,2]\cap(0,d)$, $\kappa<\kappa_{\rm c}$. Let $V^S:\mathbb{R}^d\to\mathbb{R}$ be such that $V_j^S:=(-x\cdot\nabla)^j V^S \in L_{\rm loc}^1(\mathbb{R}^d)$, and assume that
  \begin{equation}
    \label{eq:MY-norm}
    M := \sup_{x\in\mathbb{R}^d\setminus\{0\}} |x|^\alpha \sum_{j=0}^2 |V_j^S(x)| <\infty.
  \end{equation}
  Define $W_\kappa(x) := \kappa/|x|^\alpha + V^S(x)$.
  Then the following statements hold.

  \begin{enumerate}
  \item We have
    \begin{align}
      \label{eq:natural-sandwich}
      \frac{\kappa-M}{|x|^\alpha} \leq W_\kappa(x) \leq \frac{\kappa+M}{|x|^\alpha}.
    \end{align}

  \item If $M < \min\{1,\alpha\} (\kappa_{\rm c}-\kappa_+)$, then $W_\kappa$ also satisfies Assumption~\ref{mizutaniyaoconditions}.

  \item Let $\tilde\kappa<\kappa<\kappa'<\kappa_{\rm c}$ be given. If
    \begin{align}
      \label{eq:MY-smallness-fixed}
      M < \min\left\{\kappa-\tilde\kappa,\, \kappa'-\kappa,\, \alpha(\kappa_{\rm c}-\kappa_+) \right\},
    \end{align}
    then $\tilde\kappa/|x|^\alpha \leq W_\kappa(x) \leq \kappa'/|x|^\alpha$, and $W_\kappa$ satisfies Assumption~\ref{mizutaniyaoconditions}.

  \item Let $\rho_S\geq\alpha$ and let $V^S\in C^2(\mathbb{R}^d;\mathbb{R})$. Set
    \begin{align}
      \label{eq:A0}
      A_0 & := \sup_{x\in\mathbb{R}^d} \langle x\rangle^{\rho_S}|V^S(x)|, \\
      \label{eq:A1}
      A_1 & := \sup_{x\in\mathbb{R}^d} \langle x\rangle^{\rho_S+1}|\nabla V^S(x)|, \\
      \label{eq:A2}
      A_2 & := \sup_{x\in\mathbb{R}^d} \langle x\rangle^{\rho_S+2} \|{\rm Hess}(V^S(x))\|_{\mathbb{R}^d,\mathbb{R}^d},
    \end{align}
    where $\|{\rm Hess}(V^S(x))\|_{\mathbb{R}^d,\mathbb{R}^d}$ denotes the $\mathbb{R}^d\to\mathbb{R}^d$-operator norm of the Hessian of $V^S$ at $x$. Assume
    \begin{align}
      \label{eq:symbol-smallness-zero}
      A_0 & \leq \min\{\kappa-\tilde\kappa,\kappa'-\kappa\}, \\
      \label{eq:symbol-smallness-one}
      A_1 & < \alpha(\kappa_{\rm c}-\kappa_+), \\
      \label{eq:symbol-second-finite}
      A_2 & < \infty.
    \end{align}
    Then, $W_\kappa(x)$ satisfies $\tilde\kappa |x|^{-\alpha} \leq W_\kappa(x) \leq \kappa'|x|^{-\alpha}$ and Assumption~\ref{mizutaniyaoconditions}. In particular, \eqref{eq:symbol-smallness-zero}--\eqref{eq:symbol-second-finite} hold if
    \begin{align}
      \label{eq:symbol-common-constant}
      |\partial^\beta V^S(x)| \leq C_S\langle x\rangle^{-\rho_S-|\beta|}, \quad x\in\mathbb{R}^d, \ |\beta|\leq2
    \end{align}
    with
    \begin{align}
      \label{eq:common-constant-smallness}
      C_S < \min\left\{\kappa-\tilde\kappa,\, \kappa'-\kappa,\, \frac{\alpha(\kappa_{\rm c}-\kappa_+)}{\sqrt d} \right\}.
    \end{align}
  \end{enumerate}

\label{the6}
  Let $d\in\mathbb{N}$, $\alpha\in(0,2]\cap(0,d)$, $\kappa<\kappa_{\rm c}$, and $\rho>0$.
  Assume $V\in C^\infty(\mathbb{R}^d)$ satisfies \eqref{ass5} for all multi-indices $\beta$.
  Let $H_\kappa=L_\kappa-V$ and $f\in C_c^\infty(0,\infty)$ with $\operatorname{supp} f \cap \sigma_{\rm p}(H_\kappa) = \emptyset$.
  Then, for all $\nu\geq1$ there are $\theta>0$ and $T>0$ such that
  \begin{equation}
    \label{eq_the6_1}
    \left\| \mathbf{1}\left(\frac{A}{t}\leq\theta\right)f(H_\kappa) \mathrm{e}^{-i t H_\kappa}\varphi\right\|
    \lesssim_{\theta,\nu,f,T,V} t^{-\nu}\|\langle A\rangle^\nu\varphi\|, \quad t\geq T,
  \end{equation}
  holds for all $\varphi\in\mathcal{D}(\langle A\rangle^\nu)$.

\label{asympcomplhardyplusperturbationnonexistence}
  Let $d\in\mathbb{N}$, $\alpha\in(0,d)\cap(0,2]$, and $\kappa\leq\kappa_{\rm c}$. Assume that $V^L$ satisfies~\eqref{ass1} or \eqref{ass2} for some $0<\rho_L\leq1$. Then the following statements hold.

  \begin{enumerate}
  \item \label{asympcomplhardyplusperturbation:nonexistencefree}
    If $\rho_L=\alpha$, assume in addition that there is $\varepsilon_{\rm s}\in\{-1,1\}$ and $c,R>0$ so that
    \begin{align}
      \label{eq:noncancellation-equal-order}
      \varepsilon_{\rm s} \left(\frac{\kappa}{|x|^\alpha}+V^L(x) \right)
      \geq c\langle x\rangle^{-\alpha}, \quad |x|\geq R.
    \end{align}
    Then $W(L_\kappa-V^L,L_0)$ does not exist.

  \item \label{asympcomplhardyplusperturbation:nonexistencerelativelargealpha}
    Assume $\alpha>1$. Then $W(L_\kappa-V^L,L_\kappa)$ does not exist.

  \item \label{asympcomplhardyplusperturbation:nonexistencelongrangesmallalpha}
    Assume $\kappa<\kappa_{\rm c}$ and $V^L\in C^\infty(\mathbb{R}^d)$ satisfies \eqref{ass5} for all multi-indices $\beta$. Assume further that either $1/2<\alpha\leq1$ and $0<\rho_L\leq\alpha$, or $d\geq2$, $\alpha=1/2$, and $0<\rho_L\leq1/2$. Then $W(L_\kappa-V^L,L_\kappa)$ does not exist.
  \end{enumerate}

\label{cor:massiverelativisticnonexistence}
  Let $d\in\mathbb{N}$, $\alpha\in(0,d)\cap(0,2]$ and $\kappa\leq\kappa_{\rm c}$.
  Let $C_0\in\mathcal{K}_\alpha$ and $C_\kappa:=C_0-\kappa/|x|^\alpha$. Assume that $V^L$ satisfies \eqref{eq:basicassumplongrange}. Then the following statements hold.
  \begin{enumerate}
  \item If $\alpha\leq1$ and $\kappa\neq0$, then $W(C_\kappa,C_0)$ does not exist.

  \item If $\alpha\neq\rho_L$, then $W(C_\kappa-V^L,C_0)$ does not exist.
    The same conclusion holds when $\alpha=\rho_L$ provided there are $\varepsilon_{\rm s}\in\{-1,1\}$, $c>0$, and $R>0$ such that
    \begin{align}
      \label{eq:massive-equal-order-noncancellation}
      \varepsilon_{\rm s} \left(\frac{\kappa}{|x|^\alpha}+V^L(x)\right)
      \geq c\langle x\rangle^{-\alpha}, \quad |x|\geq R.
    \end{align}

  \item Assume $\alpha>1$. Then $W(C_\kappa-V^L,C_\kappa)=\operatorname*{s-lim}_{t\to\infty}\mathrm{e}^{i t(C_\kappa-V^L)}\mathrm{e}^{-i tC_\kappa}P_{\rm ac}(C_\kappa)$ does not exist.
  \end{enumerate}

\label{assumheatdifference}
  Let $H_0$ and $H$ be two selfadjoint operators in $L^2(\mathbb{R}^d)$ that are bounded from below. We assume
  \begin{enumerate}
  \item[(i)] $\mathrm{e}^{-t H}-\mathrm{e}^{-t H_0}$ is compact for a fixed $t>0$, such as $t=1$, and

  \item[(ii)] there is $\gamma>1$ such that $(\mathrm{e}^{-H}-\mathrm{e}^{-H_0})\langle x\rangle^\gamma$ is a bounded operator on $L^2(\mathbb{R}^d)$.
  \end{enumerate}

\label{heatkernelsmoothness}
  Let $H_0$ and $H$ be two selfadjoint operators in a Hilbert space $\mathcal{H}$ that are bounded below, and assume $H_0$ has (for simplicity) purely absolutely continuous spectrum. Assume $H-H_0=A^*B$ where $A$ is $H$-bounded and $A\mathrm{e}^{-t_0H}$ is $H$-smooth for every $t_0>0$ and $B$ is $H_0$-bounded and $B\mathrm{e}^{-t_0H_0}$ is $H_0$-smooth for every $t_0>0$. Then the wave operators
  \begin{align}
    W(H,H_0) := \operatorname*{s-lim}_{t\to\infty}\mathrm{e}^{i t H}\mathrm{e}^{-i t H_0}
    \quad \text{and} \quad
    W(H_0,H) := \operatorname*{s-lim}_{t\to\infty}\mathrm{e}^{i t H_0}\mathrm{e}^{-i t H}P_{\rm ac}(H)
  \end{align}
  are asymptotically complete.

We aim to apply Lemma~\ref{heatkernelsmoothness} with $H=L_\kappa-V^S$, $H_0=L_\kappa$, $A=|V^S|^{1/2}$, and $B=-(V^S)^{1/2}$. Let $\beta=s-\alpha/2$ and recall that $G:=|x|^{-s}|D|^{-\beta}$ is supersmooth by \eqref{eq:mizutaniyaosmoothing}. In Lemma~\ref{vhsmoothestimate} below, we will show that, for fixed $t>0$,
  \begin{align}
    \label{eq:acshortrangesmallalphasufficient}
    C := |V^S|^{1/2}\mathrm{e}^{-tH}|D|^\beta|x|^s \in \mathcal B(L^2(\mathbb{R}^d)).
  \end{align}
  Therefore, $CG = |V^S|^{1/2}\mathrm{e}^{-tH}$ is $H$-smooth as the product of a bounded operator and a $H$-smooth operator.
  Analogously, $(V^S)^{1/2}\mathrm{e}^{-tH_0}$ is $H_0$-smooth. Applying Lemma~\ref{heatkernelsmoothness} concludes the proof.

\label{eqsob}
  Let $d\in\mathbb{N}$, $\alpha\in(0,2] \cap (0,d)$, $\tilde\kappa\leq\kappa\leq\kappa_{\rm c}$ and let $\sigma=\Phi^{-1}(\kappa)\in(-M,(d-\alpha)/2]$. Let $\tilde\kappa/|x|^\alpha \leq V(x) \leq \kappa/|x|^\alpha$ and $s\in(0,2]$.
  \begin{enumerate}
  \item If $s<\frac{d-2\sigma}{\alpha}$, then
    \begin{align}
      \label{eq:eqsob1}
      \|(L_0)^{s/2} f\|_{2}
      \lesssim_{d,\alpha,\kappa,s} \| (L_0 - V)^{\frac{s}{2}}f\|_{2}
      \quad \text{ for all } f\in C_c^\infty(\mathbb{R}^d).
    \end{align}
  \item If $s<\frac{d}{\alpha}$, then
    \begin{align}
      \label{eq:eqsob2}
      \|(L_0 - V)^{\frac{s}{2}}f\|_{2}
      \lesssim_{d,\alpha,\kappa,s} \| (L_0)^{s/2}f\|_{2}
      \quad \text{for all}\ f\in C_c^\infty(\mathbb{R}^d).
    \end{align}
  \end{enumerate}

\begin{enumerate}
  \item In \cite[Theorem~1.2]{Killipetal2018}, only the case $V(x)=\kappa/|x|^2$ is treated. However, the same arguments as in the proof of \cite[Theorem~4.1]{Franketal2021} allow us to cover all potentials mentioned in Proposition~\ref{eqsob}.

  \item As noted in \cite[Theorem~A.1]{Franketal2018} (the latest arXiv version of \cite{Franketal2021}), we have that if $s<(d-2\sigma)/\alpha$, then $\mathcal{D}((L_\kappa)^{s/2}) \subset \mathcal{D}((L_0)^{s/2})$ and \eqref{eq:eqsob1} holds for all $f\in \mathcal{D}((L_\kappa)^{s/2})$. Moreover $C_c^\infty(\mathbb{R}^d)$ is an operator core for $(L_\kappa)^{s/2}$. Similarly, if $s<\frac{d}{\alpha}$, then $\mathcal{D}((L_0)^{s/2}) \subset \mathcal{D}((L_\kappa)^{s/2})$ and \eqref{eq:eqsob2} holds for all $f\in\mathcal{D}((L_0)^{s/2})$. Moreover, $C_c^\infty(\mathbb{R}^d)$ is an operator core for $(L_0)^{s/2}$.
  \end{enumerate}

\label{calderoncommutator}
  Let $d\geq 1$ and $0<s\leq 1$. Assume, if $s<1$, that $1-s < d/2$. Then,
  \begin{align}
    \label{eq:commutator-weight}
    \| [|D|,|x|^s]g \|_2 \lesssim_{d,s} \| |D|^{1-s}g \|_{2}.
  \end{align}
  At the endpoint $s=1$, this is understood as $\| [|D|,|x|]g \|_2 \lesssim_d \|g\|_2$.

  In particular, if $d=1$ and $1/2<s\leq1$ or $d\in\{2,3,...\}$ and $0<s<1$, then
  $$
  \| [|D|,|x|^s]g \|_2 \lesssim_{d,s} \| |D|^{1-s}g \|_2+\|g\|_2.
  $$

\label{vhsmoothestimateaux}
  Let $d\in\mathbb{N}$, $\alpha\in(0,d)\cap(0,2)$, $\kappa\leq\kappa_{\rm c}$, $\sigma=\Phi^{-1}(\kappa)$, and $t>0$.
  Assume there is $\tilde\kappa\leq\kappa$ such that $\tilde\kappa/|x|^\alpha \leq V(x)\leq \kappa/|x|^\alpha$.
  \begin{enumerate}
  \item Let $0\leq s<d/2-\sigma$ and $0\leq\gamma\leq s$.
    Then,
    \begin{align}
      \label{eq:vhsmoothestimateaux2}
      \||x|^{-s} \mathrm{e}^{-t(L_0-V)} |x|^\gamma\| \lesssim_{d,\alpha,\kappa,s,\gamma} t^{(\gamma-s)/\alpha}.
    \end{align}

  \item Let $0\leq \gamma\leq s$. Assume either $s<d/2-\sigma$, or, when $s\geq d/2-\sigma$ also $\gamma+s \leq d+\alpha-\sigma$. Then, for every $t>0$, there is $C_t>0$ such that
    \begin{align}
      \label{eq:vhsmoothestimateaux4}
      \|\langle x\rangle^{-s} \mathrm{e}^{-t(L_0-V)} |x|^\gamma\|
      \leq C_t.
    \end{align}  
  \end{enumerate}

By Trotter's formula, $\mathrm{e}^{-t(L_0-V)}(x,y)\leq\mathrm{e}^{-t L_\kappa}(x,y)$.
  We begin with the proof of Item~(1).
  By scaling, it suffices to consider $t=1$.
  We use Schur tests for the four regions $|x|,|y|\leq1$, $|x|\leq1\leq|y|$, $|y|\leq1\leq|x|$, and $|x|,|y|\geq1$.

  \smallskip
  {\bf Case $|x|,|y|\leq1$:}
  The relevant kernel is $|x|^{-s-\sigma}|y|^{\gamma-\sigma}$. We use Schur tests with weight $(|x|/|y|)^{s+\sigma}$. Then,
  \begin{align}
    |x|^{-s-\sigma}\int_{|y|\leq1}|y|^{\gamma-\sigma} \left(\frac{|x|}{|y|}\right)^{s+\sigma}
    \lesssim1, \\
    |y|^{\gamma+s}\int_{|x|\leq1}dx\, |x|^{-2(s+\sigma)}
    \lesssim 1,
  \end{align}
  where we used $s-\gamma<d-2\sigma$ (which is satisfied since $s<d/2-\sigma$ and $\gamma\geq 0$) in the first Schur test, and $s+\gamma\geq0$ and $s<d/2-\sigma$ in the second one.
  Had we not worked with the potential $|x|^{-s}$ but rather with $\langle x\rangle^{-s}$, then this Schur test would have worked with the weight $(|x|/|y|)^\sigma$, and we would not encounter the restriction $s<d/2-\sigma$.

  \smallskip
  {\bf Case $|x|\leq1\leq|y|$:}
  The relevant kernel is $|x|^{-s-\sigma}|y|^\gamma(1+|x-y|)^{-d-\alpha}$. We use Schur tests with weight $(|x|/|y|)^{s+\sigma}$. Then,
  \begin{align}
    \int_{|y|>1}dy\, |y|^{-\sigma+\gamma-s}(1+|x-y|)^{-d-\alpha} \lesssim 1,
  \end{align}
  where we used $s-\gamma>-\alpha-\sigma$ (which is satisfied because $\gamma\leq s$ and $\sigma>-\alpha$), and
  \begin{align}
    \begin{split}
      & |y|^{s+\gamma+\sigma}\int_{|x|\leq1}dx\, |x|^{-2(s+\sigma)}(1+|x-y|)^{-d-\alpha}\left(\mathbf{1}_{|x|\leq1/2}+\mathbf{1}_{1/2\leq|x|\leq1}(\mathbf{1}_{|y|\in[1,2]}+\mathbf{1}_{|y|>2})\right) \\
      & \quad \lesssim |y|^{s+\gamma +\sigma-d-\alpha} + 1
        \lesssim 1.
    \end{split}
  \end{align}
  where we used $s<d/2-\sigma$ and $s+\gamma\leq d+\alpha-\sigma$ (which is satisfied since $s+\gamma\leq d-2\sigma<d+\alpha-\sigma$).


  \smallskip
  {\bf Case $|y|\leq1\leq|x|$:}
  The relevant kernel is $|x|^{-s}|y|^{\gamma-\sigma}(1+|x-y|)^{-d-\alpha}$. We use Schur tests with weight $(|x|/|y|)^{-\gamma+\sigma}$. Then,
  \begin{align}
    \begin{split}
      |x|^{\sigma-s-\gamma} \int_{|y|\leq1}dy\, |y|^{2\gamma-2\sigma}(1+|x-y|)^{-d-\alpha}(\mathbf{1}_{|x|\in[1,2]}+\mathbf{1}_{|x|\geq2})
      \lesssim1,
    \end{split}
  \end{align}
  where we used $\sigma-s-\gamma \leq d+\alpha$ and $2\gamma>2\sigma-d$ (which is satisfied since $-\alpha<\sigma\leq(d-\alpha)/2$ and $s,\gamma\geq0$), and
  \begin{align}
    \begin{split}
      \int_{|x|\geq1}dx\, |x|^{-\sigma+\gamma-s}(1+|x-y|)^{-d-\alpha} \lesssim1
    \end{split}
  \end{align}
  since $s-\gamma>-\alpha-\sigma$ (which is satisfied because $\gamma\leq s$ and $\sigma>-\alpha$).


  \smallskip
  {\bf Case $|x|,|y|\geq1$:}
  The relevant kernel is $|x|^{-s}|y|^{\gamma}(1+|x-y|)^{-d-\alpha}$. We use Schur tests with weight $(|x|/|y|)^\delta$ with $\gamma-\alpha<\delta<d+\alpha-s$; such a $\delta$ exists because $\gamma+s<d-2\sigma<d+2\alpha$, which follows from $\sigma>-\alpha$. Then
  \begin{align}
    \begin{split}
      & |x|^{\delta-s}\int_{|y|>1}dy\,(1+|x-y|)^{-d-\alpha}|y|^{\gamma-\delta} \left(\mathbf{1}_{|y|\leq|x|/2}+\mathbf{1}_{|x|/2\leq|y|\leq2|x|}+\mathbf{1}_{|y|\geq2|x|}\right) \\
      & \quad \lesssim |x|^{\delta-s} \cdot |x|^{\gamma-\delta} \lesssim 1
    \end{split}
  \end{align}
  since $s-\gamma\geq0>-\alpha$, and
  \begin{align}
    \begin{split}
      & |y|^{\delta+\gamma} \int_{|x|\geq1}dx\, (1+|x-y|)^{-d-\alpha}|x|^{-s-\delta}\left(\mathbf{1}_{|x|\leq|y|/2}+\mathbf{1}_{|y|/2\leq |x|\leq2|y|} + \mathbf{1}_{|x|\geq2|y|}\right) \\
      & \quad \lesssim |y|^{\delta+\gamma} ( |y|^{-\alpha-s-\delta}+|y|^{-s-\delta})
        \lesssim 1.
    \end{split}
  \end{align}
  This concludes the proof of Item~(1).


  \smallskip
  We now prove Item~(2). When $s<d/2-\sigma$, this follows from the previous Schur tests and $\|\langle x\rangle^{-s}\mathrm{e}^{-t L_\kappa}|x|^\gamma\| \leq \||x|^{-s}\mathrm{e}^{-t L_\kappa}|x|^\gamma\|$. When $s\geq d/2-\sigma$, we re-inspect the Schur test in the region $|x|\leq t^{1/\alpha}$, which is the only region where this restriction was used.
  When also $|y|\leq t^{1/\alpha}$, we use the weight $(|x|/|y|)^\sigma$ and get
  \begin{align}
    t^{2\sigma/\alpha-d/\alpha} \langle x\rangle^{-s}\int_{|y|<t^{1/\alpha}}|y|^{\gamma-2\sigma}
    & \lesssim t^{\gamma/\alpha}, \\
    t^{2\sigma/\alpha-d/\alpha} |y|^{\gamma} \int_{|x|<t^{1/\alpha}}\langle x\rangle^{-s}|x|^{-2\sigma}
    & \lesssim t^{\gamma/\alpha}.
  \end{align}
  where we used $\sigma\leq(d-\alpha)/2<d/2$.
  In the region $|x|\leq t^{1/\alpha}\leq|y|$ we use the weight $(|x|/|y|)^{\sigma}(\langle x_t\rangle/\langle y_t\rangle)^s$ with $x_t=x/t^{1/\alpha}$ and $y_t=y/t^{1/\alpha}$. The $\sup_{|x_t|<1}\int_{|y_t|>1}dy$-Schur test is the same, using $\gamma\leq s$. The other Schur test is
  \begin{align}
    \begin{split}
      & t^{1+d/\alpha}|y_t|^{s+\gamma+\sigma}\int_{|x_t|\leq1}dx\, \langle x_t\rangle^{-s}\langle x\rangle^{-s} |x_t|^{-2\sigma}(t^{1/\alpha}+|x-y|)^{-d-\alpha} \\
      & \quad \lesssim_t |y_t|^{s+\gamma+\sigma-d-\alpha}+1 \lesssim1, \quad |y_t|>1,
    \end{split}
  \end{align}
  where now we just used $s+\gamma\leq d+\alpha-\sigma$.
  This concludes the proof.

\label{vhsmoothestimate}
  Let $d\in\mathbb{N}$, $\alpha\in(0,d)\cap(0,1]$, $\kappa<\kappa_{\rm c}$, $\sigma=\Phi^{-1}(\kappa)$, and $t>0$.
  Assume there is $\tilde\kappa\leq\kappa$ such that $\tilde\kappa/|x|^\alpha \leq V(x)\leq \kappa/|x|^\alpha$.
  Assume also that either
  \begin{align*}
    \alpha < s \leq \min\{1,3\alpha/2\}
  \end{align*}
  or
  \begin{align*}
    \alpha=1 \quad \text{and} \quad \frac12<s\leq1.
  \end{align*}


  \begin{enumerate}
  \item Let $s<d/2-\sigma$. Then,
    \begin{align}
      \label{eq:vhsmoothestimate1}
      \||x|^{-s}\mathrm{e}^{-t(L_0-V)}|D|^{s-\alpha/2}|x|^s\| \lesssim_{d,\alpha,\kappa,s} t^{-(s-\alpha/2)/\alpha}.
    \end{align}

  \item Assume
    \begin{align}
      \label{eq:vhsmooth-sobolev-condition}
      s < (d + \alpha - 2\sigma)/2, \\
      \label{eq:vhsmooth-kernel-condition}
      s < (d + \alpha - \sigma)/2.
    \end{align}
    Then, for every $t>0$, there is $C_t>0$ such that
    \begin{align}
      \label{eq:vhsmoothestimate2}
      \|\langle x\rangle^{-s}\mathrm{e}^{-t(L_0-V)}|D|^{s-\alpha/2}|x|^s\|
      \lesssim_{d,\alpha,\kappa,s} C_t.
    \end{align}
    In particular, \eqref{eq:acshortrangesmallalphasufficient} holds.
  \end{enumerate}

{\bf Case $\alpha<1$:}
  We first show Item (1). By scaling, it suffices to consider $t=1$. Let $\beta = s - \alpha/2$. By our assumptions, $\beta \in (\alpha/2, \min\{1,3\alpha/2\}-\alpha/2]$.
  We consider
  \begin{align}
    T := |x|^s |D|^\beta \mathrm{e}^{-(L_0-V)}|x|^{-s}.
  \end{align}
  We commute $|D|^\beta$ to the left and write $T = T_1 - T_2$, where
  \begin{align}
    T_1 & := |D|^\beta|x|^s\mathrm{e}^{-(L_0-V)}|x|^{-s}, \\
    T_2 & := [|D|^\beta, |x|^s] \mathrm{e}^{-(L_0-V)}|x|^{-s}.
  \end{align}

  \smallskip
  \noindent {\bf Bound for $T_2$:}
  The integral kernel of $[|D|^\beta, |x|^s]$ is bounded by $c_{d,\beta} \frac{||x|^s - |y|^s|}{|x-y|^{d+\beta}}$. Since $s \in (0, 1]$, we can use $||x|^s - |y|^s| \leq |x-y|^s$. Thus, the kernel is bounded pointwise by a multiple of $|x-y|^{-(d+\beta-s)}$. Since $\beta - s = -\alpha/2$, this is the convolution kernel of the Riesz potential $|D|^{-\alpha/2}$. Because the constituent operators possess positive integral kernels, we have the pointwise bound
  \begin{align}
    |T_2 f|
    \lesssim |D|^{-\alpha/2}|x|^{-\alpha/2} \left(|x|^{\alpha/2} \mathrm{e}^{-(L_0-V)}|x|^{-s} |f| \right).
  \end{align}
  Therefore,
  \begin{align}
    \|T_2 f\|_2
    \lesssim \left\| |x|^{\alpha/2} \mathrm{e}^{-(L_0-V)} |x|^{-s} |f| \right\|_2
    \lesssim \|f\|_2
  \end{align}
  by Hardy's inequality and \eqref{eq:vhsmoothestimateaux2} in Lemma~\ref{vhsmoothestimateaux} (applied with $\gamma = \alpha/2$ there), which requires $\alpha/2 \leq s$ and $s < d/2 - \sigma$; this is possible due to our assumption $\sigma < (d-\alpha)/2$. Thus, $\|T_2\| \lesssim 1$.

  \smallskip\noindent {\bf Bound for $T_1$:}
  To estimate $T_1$, we use the equivalence of Sobolev norms in Proposition~\ref{eqsob}, i.e., $|D|^{2\beta} \lesssim (L_0-V)^{2\beta/\alpha}$ whenever $\beta < (d-2\sigma)/2$ and $\beta\leq \alpha$. The assumption $\beta\leq\alpha$ is ensured by $s\leq3\alpha/2$.
  The assumption $\beta < (d-2\sigma)/2$ is equivalent to $s<(d-2\sigma+\alpha)/2$; this is justified here since $s<d/2-\sigma$.
  Thus, by Proposition~\ref{eqsob},
  \begin{align}
    \begin{split}
      \|T_1 f\|_2
      & = \left\| |D|^\beta \left( |x|^s \mathrm{e}^{-(L_0-V)}|x|^{-s} f \right) \right\|_2 \\
      & \lesssim \left\| (L_0-V)^{\beta/\alpha} \left(|x|^s \mathrm{e}^{-(L_0-V)}|x|^{-s} f\right) \right\|_2.
    \end{split}
  \end{align}
  Next, by the spectral theorem with $\beta\leq\alpha$,
  $$
  \| (L_0-V)^{\beta/\alpha} u \|_2
  \leq \| u \|_2^{1-\beta/\alpha} \| (L_0-V) u \|_2^{\beta/\alpha}
  \lesssim \|u\|_2 + \| (L_0-V) u\|_2.
  $$
  Thus, letting
  $$
  B = |x|^s\mathrm{e}^{-(L_0-V)}|x|^{-s},
  $$
  it suffices to prove that $\|(L_0-V) B\| \lesssim 1$ since $\|B\| \lesssim 1$ follows from Lemma~\ref{vhsmoothestimateaux}.

  We now show $\|(L_0-V) B\| \lesssim 1$ by commuting $L_0-V$ next to $\mathrm{e}^{-(L_0-V)}$. We have $(L_0-V) (|x|^s u) = [ (-\Delta)^{\alpha/2}, |x|^s ] u + |x|^s (L_0-V) u$. Letting $u = \mathrm{e}^{-(L_0-V)} |x|^{-s} f$, we split $(L_0-V) B = W + C$, where
  \begin{align}
    W f & = [ (-\Delta)^{\alpha/2}, |x|^s ] \mathrm{e}^{-(L_0-V)} |x|^{-s} f, \\
    C f & = |x|^s (L_0-V) \mathrm{e}^{-(L_0-V)} |x|^{-s} f.
  \end{align}
  To bound $C$, we use that for every $\varepsilon>0$, we have
  \begin{align}
    \label{eq:derivativeheatkernel}
    \left| (L_0-V) \mathrm{e}^{-t(L_0-V)}(x,y) \right|
    \lesssim_\varepsilon t^{-1-\frac{d}{\alpha}} \left(1\wedge\frac{|x|}{t^{1/\alpha}}\right)^{-\sigma} \left(1\wedge\frac{|y|}{t^{1/\alpha}}\right)^{-\sigma} \left(1+\frac{|x-y|}{t^{1/\alpha}}\right)^{-d-\alpha+\varepsilon}
  \end{align}
  by the bounds for $\mathrm{e}^{-t(L_0-V)}$, Cauchy's integral formula, and a Phragm\'en--Lindel\"of argument \cite{DuongRobinson1996,Merz2022}; we give a full proof in Proposition~\ref{thm-ptk}.
  Accepting \eqref{eq:derivativeheatkernel} and taking $\varepsilon<\min\{\alpha,\alpha+\sigma\}$, we can argue exactly as in the proof of Lemma~\ref{vhsmoothestimateaux} to infer $\|C\|\lesssim1$ whenever $s<d/2-\sigma$.

  To bound $W$, we note that the kernel of $[ (-\Delta)^{\alpha/2}, |x|^s ]$ is bounded by $|x-y|^{-d-\alpha+s}$, which is the kernel of the Riesz potential $|D|^{\alpha-s}$ since $\alpha<s$. Applying the pointwise bound and Hardy's inequality (using $s\leq3\alpha/2$) yields
  \begin{align}
    \begin{split}
      \| W f \|_2
      & \lesssim \left\| |D|^{\alpha-s} \left( \mathrm{e}^{-(L_0-V)} |x|^{-s} |f| \right) \right\|_2 \\
      & \lesssim \left\| |x|^{s-\alpha} \mathrm{e}^{-(L_0-V)} |x|^{-s} |f| \right\|_2
        \lesssim \|f\|_2
    \end{split}
  \end{align}
  by \eqref{eq:vhsmoothestimateaux2} in Lemma~\ref{vhsmoothestimateaux} (with $\gamma=s-\alpha$ there).
  Thus, we have proved $\|(L_0-V) B\| \lesssim 1$, which yields $\|T_1\| \lesssim 1$. Combining the bounds for $T_1$ and $T_2$ yields $\|T\| \lesssim 1$. This concludes the proof of Item~(1).

  \smallskip 
  The proof of Item~(2) is analogous, but uses \eqref{eq:vhsmoothestimateaux4} in Lemma~\ref{vhsmoothestimateaux}. Let us give the details. Here we define
  \begin{align}
    T & := |x|^s|D|^\beta \mathrm{e}^{-(L_0-V)}\langle x\rangle^{-s}, \\
    B & := |x|^s \mathrm{e}^{-(L_0-V)}\langle x\rangle^{-s}.
  \end{align}
  First, let us recall the decomposition of $T=T_1-T_2$. The operator $T_2$ is bounded as before using \eqref{eq:vhsmoothestimateaux4} in Lemma~\ref{vhsmoothestimateaux} (with $\gamma=\alpha/2$ there) and the analysis of $T_1$ is reduced to that of $B$ using Proposition~\ref{eqsob}, which requires $s<(d+\alpha-2\sigma)/2$.
  Using \eqref{eq:vhsmoothestimateaux4} in Lemma~\ref{vhsmoothestimateaux} (with $\gamma=s$ there), we have $\|B\|\lesssim1$ when $s<(d+\alpha-\sigma)/2$. Moreover, we have $\||x|^s(L_0-V)\mathrm{e}^{-(L_0-V)}\langle x\rangle^{-s}\|\lesssim1$ (the analog of $\|C\|\lesssim1$) when $s<(d+\alpha-\sigma)/2$; here we need to choose $\varepsilon<\min\{\alpha,\alpha+\sigma,d+\alpha-\sigma-2s\}$ in \eqref{eq:derivativeheatkernel}. Finally, we have $\|[(-\Delta)^{\alpha/2},|x|^s]\mathrm{e}^{-(L_0-V)}\langle x\rangle^{-s}\|\lesssim1$ using \eqref{eq:vhsmoothestimateaux4} in Lemma~\ref{vhsmoothestimateaux} (with $\gamma=s-\alpha$ there) when $s<(d+2\alpha-\sigma)/2$.


  \smallskip
  {\bf Case $\alpha=1$:} From the above proof for $\alpha<1$, it transpires that we only need to re-verify the boundedness of $W$, where we used $s>\alpha$ when $\alpha<1$. Let us show that when $\alpha=1$, it suffices to assume $s>1/2$.
  We apply Lemma~\ref{calderoncommutator} with $g=\mathrm{e}^{-(L_0-V)}\omega^{-s}f$, where $\omega(x)=|x|$ in Item~(1) and $\omega(x)=\langle x\rangle$ in Item~(2).

  Since $\sigma<(d-1)/2$ and $s>1/2$, we have $2(1-s)<1<d-2\sigma$. Hence, Proposition~\ref{eqsob}, applied with exponent $2(1-s)$, gives
  $$
  \| |D|^{1-s}g\|_2 \lesssim \|(L_0-V)^{1-s}g\|_2.
  $$
  Therefore, by the spectral theorem,
  \begin{align*}
    \|(L_0-V)^{1-s}\mathrm{e}^{-(L_0-V)} \omega^{-s}f\|_2
    \leq \|(L_0-V)^{1-s}\mathrm{e}^{-(L_0-V)/2}\| \|\mathrm{e}^{-(L_0-V)/2} \omega^{-s}f\|_2
    \lesssim \|f\|_2;
  \end{align*}
  here we used \eqref{eq:vhsmoothestimateaux2} in Lemma~\ref{vhsmoothestimateaux} (with $\gamma=0$ there) when $\omega(x)=|x|$ for Item~(1) and $\langle x\rangle^{-s}\leq1$ for Item~(2). Thus,
  $$
  \|[|D|,|x|^s]\mathrm{e}^{-(L_0-V)}|x|^{-s}f\|_2
  + \|[|D|,|x|^s]\mathrm{e}^{-(L_0-V)}\langle x\rangle^{-s}f\|_2
  \lesssim \|f\|_2.
  $$
  This shows the boundedness of $W$ and concludes the proof for $\alpha=1$ since the estimates of $T_2$ and $C$, as well as the final interpolation argument for $T_1$ are the same.

Since for $\alpha\in(1,d)$ we also have, according to \cite[Theorem~1.3]{MizutaniYao2021},
  \begin{align}
    \label{eq:mizutaniyaosmoothingshortrange}
    \sup_{z\in\mathbb{C}\setminus[0,\infty)}\||x|^{-\alpha/2}(L_0 - V - z)^{-1}|x|^{-\alpha/2}\| < \infty,
  \end{align}
  Kato's smoothness approach also yields another proof of asymptotic completeness of $W(L_\kappa,L_0)$ for $\alpha\in(1,2]$ when $\kappa<\kappa_{\rm c}$. The advantage of our above proof using the semigroup framework is that we can also treat $\kappa=\kappa_{\rm c}$.

\label{prop:analyticextension}
  Let $f\in C_c^\infty(\mathbb{R})$. Then there exists $\tilde f\in C_c^\infty(\mathbb{C})$, called an {\em almost analytic extension of $f$} such that
  $$
  \tilde f\big|_{\mathbb{R}} = f
  $$
  and for every $N\in\mathbb{N}$ there is a constant $C_N>0$ such that
  $$
  \left| \frac{\partial \tilde f}{\partial\overline z}(z) \right|
  \leq C_N\, |\operatorname{Im}(z)|^{N},  \quad z\in\mathbb{C}.
  $$
  Moreover, for every selfadjoint operator $A$ and every such $f$, we have the Helffer--Sj\"ostrand formula
  \begin{align}
    \label{eq:hs}
    f(A) = \frac{1}{2\pi i} \int_{\mathbb{C}}\frac{\partial\tilde f}{\partial \overline z}(z)(z-A)^{-1} \, dz\wedge d\overline z,
  \end{align}
  where the integral converges absolutely in operator norm.
  More generally, for $n\in\mathbb{N}$,
  \begin{align}
    \label{eq:hsderivative}
    f^{(n)}(A) = \frac{n!}{2\pi i}\int_{\mathbb{C}}\frac{\partial\tilde f}{\partial \overline z}(z)(z-A)^{-n-1}\, dz\,\wedge d\overline z.
  \end{align}

\label{lem:functional-calculus-commutator}
  Let $\mathcal H$ be a Hilbert space, let $A$ be selfadjoint on $\mathcal H$, and let $X\in\mathcal B(\mathcal H)$. Let $f\in L^\infty(\mathbb{R})\cap C^\infty(\mathbb{R})$ be such that
  \begin{align}
    \label{eq:f-S0}
    \sup_{x\in\mathbb{R}} \langle x\rangle^k |f^{(k)}(x)|<\infty, \quad k\in\mathbb{N}_0.
  \end{align}
  For $N\in\mathbb{N}$ let $\widetilde f_N$ be an almost analytic extension of $f$.
  Let also $R_t(z) := \left(z-A/t\right)^{-1}$.

  \begin{enumerate}
  \item Assume that $X\in C^1(A)$, i.e.,
    $$
    X \mathcal{D}(A) \subset \mathcal{D}(A)
    $$
    and that the commutator
    $$
    [X,A] = XA-AX, \quad \mathcal{D}([X,A]) = \mathcal{D}(A),
    $$
    extends to a bounded operator on $\mathcal H$, denoted again by $[X,A]$. Then, for every $N\geq2$,
    \begin{align}
      \label{eq:first-commutator-HS-corrected}
      \left[X,f\left(\frac{A}{t}\right)\right]
      = \frac{1}{2\pi i\,t} \int_{\mathbb{C}} \overline{\partial} \widetilde f_N(z) R_t(z)[X,A]R_t(z)\, dz\wedge d\overline z
    \end{align}
    with
    \begin{align}
      \label{eq:first-functional-commutator}
      \left\|\left[X,f\left(\frac At\right)\right]\right\|
      \lesssim_f \frac1t\|[X,A]\|,
      \qquad t>0.
    \end{align}

  \item Assume in addition that $X\in C^2(A)$, i.e.,
    $$
    [X,A] \mathcal{D}(A) \subset \mathcal{D}(A)
    $$
    and that
    $$
    [[X,A],A] = [X,A]A-A[X,A], \quad \mathcal{D}([[X,A],A]) = \mathcal{D}(A),
    $$
    extends to a bounded operator on $\mathcal H$, denoted again by $[[X,A],A]$. Then, for every $N\geq3$,
    \begin{align}
      \label{eq:second-functional-commutator}
      \left[X,f\left(\frac At\right)\right]
      = \frac1t f'\left(\frac At\right)[X,A] + \mathcal{E}_f(t)
    \end{align}
    where
    \begin{align}
      \label{eq:explicit-Rf}
      \mathcal{E}_f(t) := \frac{1}{2\pi i\,t^2} \int_{\mathbb{C}} \overline\partial\widetilde f_N(z) R_t(z)^2[[X,A],A]R_t(z)\, dz\wedge d\overline z.
    \end{align}
    The integral in \eqref{eq:explicit-Rf} is an absolutely convergent Bochner integral in $\mathcal B(\mathcal H)$ and
    \begin{align}
      \label{eq:second-functional-remainder}
      \|\mathcal{E}_f(t)\| \lesssim_f \frac1{t^2}\|[[X,A],A]\|, \quad t>0.
    \end{align}
  \end{enumerate}

\label{lem5}
  Let $\alpha\in(0,2]\cap(0,d)$ and $\kappa<\kappa_{\rm c}$.
  The commutator $i[L_\kappa,A]$ is well-defined as a bounded operator mapping $H^{\alpha/2}(\mathbb{R}^d) \to H^{-\alpha/2}(\mathbb{R}^d)$ in the sense of quadratic forms. In particular,
  \begin{equation}
    \label{eq_lem5_1}
    \langle \psi, i[L_\kappa,A] \varphi\rangle
    = \alpha \langle L_\kappa^{1/2}\psi,L_\kappa^{1/2}\varphi\rangle
  \end{equation}
  holds for all $\psi,\varphi\in H^{\alpha/2}(\mathbb{R}^d)$ and
  \begin{equation}
    \label{eq_lem5_2}
    \langle \psi, i[L_\kappa,A] \varphi\rangle
    = i\langle L_\kappa\psi,A\varphi\rangle - i \langle A\psi,L_\kappa\varphi\rangle
    = \alpha \langle \psi,L_\kappa\varphi\rangle
  \end{equation}
  holds for all $\psi,\varphi\in \mathcal{D}(A)\cap\mathcal{D}(L_\kappa)$.

We define the quadratic form
  \begin{equation}
    q_\kappa(\psi,\varphi)
    = \langle |D|^{\alpha/2}\psi,|D|^{\alpha/2}\varphi\rangle - \kappa \langle |x|^{-\alpha/2}\psi,|x|^{-\alpha/2}\varphi\rangle
  \end{equation}
  for $\psi,\varphi\in H^{\alpha/2}(\mathbb{R}^d)$. By Hardy's inequality with $\kappa<\kappa_{\rm c}$, $q_\kappa$ is nonnegative and closed (since $H^{\alpha/2}(\mathbb{R}^d)$ is complete), and we have $q_\kappa(\psi,\varphi) = \langle L_\kappa^{1/2}\psi,L_\kappa^{1/2}\varphi\rangle$ by the first representation theorem. Using $\mathrm{e}^{i t A}x \mathrm{e}^{-i t A} = \mathrm{e}^{t} x$ and $\mathrm{e}^{i t A}D \mathrm{e}^{-i t A} = \mathrm{e}^{-t}D$, we have
  \begin{equation}
    \label{eq_lem5_3}
    q_\kappa(\mathrm{e}^{-i t A} \psi, \mathrm{e}^{-i t A} \varphi) = \mathrm{e}^{-\alpha t} q_\kappa(\psi,\varphi)
  \end{equation}
  for all $\psi,\varphi\in C_c^\infty(\mathbb{R}^d\setminus\{0\})$. Since $C_c^\infty(\mathbb{R}^d\setminus\{0\})$ is dense in $H^{\alpha/2}(\mathbb{R}^d)$ for $\alpha\leq d$ (see, e.g., \cite[Theorem~1.70]{Bahourietal2011}), \eqref{eq_lem5_3} also holds for all $\psi,\varphi\in H^{\alpha/2}(\mathbb{R}^d)$. Therefore, the form commutator is defined by
  \begin{equation}
    \label{eq_lem5_4}
    i[L_\kappa,A]_q(\psi,\varphi)
    := -\frac{d}{dt}q_\kappa(\mathrm{e}^{-i t A}\psi, \mathrm{e}^{-i t A}\varphi)\big|_{t=0}
    = \alpha q_\kappa(\psi,\varphi)
  \end{equation}
  and we have $|i[L_\kappa,A]_q(\psi,\varphi)| \leq \alpha \|L_\kappa^{1/2}\psi\| \|L_\kappa^{1/2}\varphi\|$. This implies that
  $$
  i[L_\kappa,A]: H^{\alpha/2}(\mathbb{R}^d)\rightarrow H^{-\alpha/2}(\mathbb{R}^d)
  $$
  exists with
  \begin{equation}
    \label{eq_lem5_5}
    i [L_\kappa,A]_q(\psi,\varphi)
    = \langle \psi,i[L_\kappa,A]\varphi\rangle
  \end{equation}
  by the Riesz representation theorem.
  By \eqref{eq_lem5_3}, $\mathcal{D}(L_\kappa)$ is invariant under dilations. Thus, differentiating $\langle\psi, \mathrm{e}^{itA}L_\kappa\mathrm{e}^{-itA}\varphi\rangle$ as in \eqref{eq_lem5_4} yields \eqref{eq_lem5_2}.

\label{lem12}
  Let $\mu\in[0,2]$. Then,
  \begin{equation}
    \langle D\rangle^{-\mu/2}\langle x\rangle^{-\mu/2}\langle A\rangle^{\mu}\langle x\rangle^{-\mu/2}\langle D\rangle^{-\mu/2} \in \mathcal B(L^2(\mathbb{R}^d)).
  \end{equation}

It suffices to prove that $\langle A\rangle^{\mu/2}\langle x\rangle^{-\mu/2}\langle D\rangle^{-\mu/2}$ is bounded for $0\leq\mu\leq2$. We define $F(z)=\langle A\rangle^z\langle x\rangle^{-z}\langle D\rangle^{-z}$ for $z\in\mathbb{C}$ with $0\leq \operatorname{Re}(z) \leq1$ and apply Stein's complex interpolation theorem (see, e.g., \cite[Theorem~1.3.7]{Grafakos2014C}).
  All expressions involving $F(z)$ are initially interpreted on the Schwartz space $\mathcal S(\mathbb{R}^d)$. For $\varphi,\psi\in\mathcal S(\mathbb{R}^d)$, the function $z\mapsto\langle\varphi,F(z)\psi\rangle$ is analytic in the open strip and continuous on its closure. The boundary estimates below are uniform on this common core and therefore give bounded closures on the two boundary lines. Stein's interpolation theorem then yields the bounded operator in the interior, and the resulting estimate extends from $\mathcal S(\mathbb{R}^d)$ to $L^2$ by density.

  We first note that $\langle A\rangle\langle x\rangle^{-1}\langle D\rangle^{-1}$ is bounded. Indeed, since $A=x\cdot D-i\cdot d/2$,
  $$
  A \langle x\rangle^{-1} \langle D\rangle^{-1}
  = x \langle x\rangle^{-1} D \langle D\rangle^{-1}
  + [A,\langle x\rangle^{-1}] \langle D\rangle^{-1} - \frac{id}{2} \langle x\rangle^{-1}\langle D\rangle^{-1},
  $$
  which is bounded since $[A,\langle x\rangle^{-1}]=-ix\cdot\nabla\langle x\rangle^{-1}$ is also bounded.

  Next, $z\mapsto\langle \varphi,F(z)\psi\rangle$ is analytic in the open strip $0<\operatorname{Re}(z)<1$ and continuous on $0\leq \operatorname{Re}(z) \leq1$ for $\varphi,\psi\in C_c^\infty(\mathbb{R}^d)$. Indeed, $\langle x\rangle^{-z}=\mathrm{e}^{-z\log\langle x\rangle}$ is a multiplication operator, $\langle D\rangle^{-z}$ is a Fourier multiplier, and $\langle A\rangle^z$ is defined by the functional calculus of the selfadjoint operator $A$.

  Since each factor of $F(i\lambda) = \langle A\rangle^{i\lambda}\langle x\rangle^{-i\lambda}\langle D\rangle^{-i\lambda}$ is unitary, $\|F(i\lambda)\|=1$ on the line $\operatorname{Re}(z)=0$. 
  On the right end of the strip $\operatorname{Re}(z)=1$, we have
  \begin{align}
    \label{eq:F1ilambda}
    \begin{split}
      F(1 + i\lambda)
      & = \langle A\rangle^{1+i\lambda}\langle x\rangle^{-1-i\lambda} \langle D\rangle^{-1-i\lambda} \\
      & = \langle A\rangle^{i\lambda} \cdot \langle A\rangle\langle x\rangle^{-i\lambda} \langle A\rangle^{-1} \cdot \langle A\rangle\langle x\rangle^{-1}\langle D\rangle^{-1} \cdot \langle D\rangle^{-i\lambda}.
    \end{split}
  \end{align}
  It remains to show
  \begin{align}
    \label{eq:AxAinverse}
    \|\langle A\rangle\langle x\rangle^{-i\lambda}\langle A\rangle^{-1}|\|\lesssim\langle\lambda\rangle.
  \end{align}
  To this end, we claim
  \begin{align}
    \label{eq:AxAinverse-squared}
    \| \langle A\rangle^2\langle x\rangle^{-i\lambda}\langle A\rangle^{-2} \|
    \lesssim \langle\lambda\rangle^2.
  \end{align}
  To show \eqref{eq:AxAinverse-squared}, let us denote the multiplication operator $\langle x\rangle^{-i\lambda}$ by $M_\lambda$ and observe
  \begin{align*}
    [A,M_\lambda] & = -ix\nabla M_\lambda, \\
    \|[A,M_\lambda]\| & \lesssim |\lambda|, \\
    \|[A,[A,M_\lambda]]\| & \lesssim |\lambda| + |\lambda|^2.
  \end{align*}
  Thus, \eqref{eq:AxAinverse-squared} follows by expanding the operator in this formula and using the above estimates.
  Applying complex interpolation for the family $\langle A\rangle^z M_\lambda \langle A\rangle^{-z}$ with $0\leq\operatorname{Re}(z)\leq2$ then yields \eqref{eq:AxAinverse}.

  Thus, $\|F(1+i\lambda)\|\lesssim\langle\lambda\rangle$ for all $\lambda\in\mathbb{R}$, which concludes the proof.

\label{lem:commutators-spectral-cutoff}
  Let $d\in\mathbb{N}$, $\alpha\in(0,2]\cap(0,d)$, $\kappa<\kappa_{\rm c}$, and $\rho>0$. Assume that $V\in C^2(\mathbb{R}^d)$ satisfies \eqref{ass5} for all multi-indices $\beta\in\mathbb{N}_0^d$ with $|\beta|\leq2$. Let $H:=L_\kappa-V$ and $\lambda\in\mathbb{R}$ be such that $H+\lambda\geq\delta>0$ for some $\delta>0$.
  Let $\chi\in C^\infty(\mathbb{R})$ satisfy, for some $\theta>0$,
  $$
  \chi(s)=0
  \quad\text{for }s\leq\frac{\theta}{2},
  \qquad
  \chi(s)=1
  \quad\text{for }s\geq\theta.
  $$
  Then,
  \begin{align}
    \label{eq:chi-VL-commutator}
    \|[\chi(A/t),V]\| & \lesssim_\chi (\|V\|_\infty+\|x\cdot\nabla V\|_\infty) t^{-1}, \quad t>0.
  \end{align}
  Moreover, $R_\lambda:=(\lambda+H)^{-1}\in C^1(A)$ and
  \begin{align}
    \label{eq:chi-resolvent-commutator}
    \|[\chi(A/t),R_\lambda]\| & \lesssim_{\chi,V,\delta} t^{-1}, \quad t>0.
  \end{align}

\label{lem:fractional-A-sandwich}
  Let $0<\rho<1$, $\rho\leq\alpha<2$, and suppose that $V\in C^\infty(\mathbb{R}^d)$ satisfies \eqref{ass5} for all multi-indices $\beta\in\mathbb{N}_0^d$. Then,
  \begin{align}
    \label{eq:fractional-sandwich}
    \langle D\rangle^{-\alpha/2} \langle A\rangle^\rho V \langle D\rangle^{-\alpha/2} \in\mathcal B(L^2(\mathbb{R}^d)).
  \end{align}

Set
  $$
  w(x):=\langle x\rangle^{-\rho/2},
  \qquad
  b(x):=\langle x\rangle^\rho V(x).
  $$
  Then $V=w^2b$. By assumption, $b\in W^{1,\infty}(\mathbb{R}^d)$. Moreover, $x\cdot\nabla w\in L^\infty(\mathbb{R}^d)$. Thus, by Lemma~\ref{lem:fractional-A-commutator} (using $\rho<1$),
  \begin{align}
    \label{eq:fractional-w-comm}
    [\langle A\rangle^\rho,w] \in\mathcal B(L^2).
  \end{align}
  The following identities are first understood on $C_c^\infty(\mathbb{R}^d)$ (or another common core), and the estimates show that the operator sandwiched between the $\langle D\rangle^{-\alpha/2}$ extends uniquely to a bounded operator on $L^2$. Thus, on $C_c^\infty(\mathbb{R}^d)$,
  \begin{align}
    \label{eq:fractional-sandwich-decomp}
    \langle A\rangle^\rho V
    = \langle A\rangle^\rho w^2b
    = w\langle A\rangle^\rho wb + [\langle A\rangle^\rho,w] wb.
  \end{align}
  The second term is bounded by \eqref{eq:fractional-w-comm} since $w$ and $b$ are bounded. Hence,
  $$
  \langle D\rangle^{-\alpha/2} [\langle A\rangle^\rho,w] w b \langle D\rangle^{-\alpha/2} \in \mathcal B(L^2).
  $$
  For the first term in \eqref{eq:fractional-sandwich-decomp}, Lemma~\ref{lem12}, applied with $\mu=\rho$, yields
  \begin{align}
    \label{eq:fractional-lem12-use}
    T_\rho := \langle D\rangle^{-\rho/2} w\langle A\rangle^\rho w\langle D\rangle^{-\rho/2} \in\mathcal B(L^2).
  \end{align}
  Therefore,
  \begin{align}
    \label{eq:fractional-first-factorization}
    \langle D\rangle^{-\alpha/2} w\langle A\rangle^\rho w b \langle D\rangle^{-\alpha/2}
    = \langle D\rangle^{-(\alpha-\rho)/2} T_\rho \left(\langle D\rangle^{\rho/2} b \langle D\rangle^{-\alpha/2}\right).
  \end{align}
  The first two factors on the right-hand side are bounded. We claim that the last factor, i.e., $\langle D\rangle^{\rho/2}b\langle D\rangle^{-\alpha/2}$, is also bounded. Indeed, multiplication by a $W^{1,\infty}$ function (like $b$ here) is bounded on $H^r(\mathbb{R}^d)$ for every $0\leq r\leq1$. Indeed, the statement is immediate for $r=0$, while for $r=1$ it follows from $\nabla(bu) = b\nabla u+(\nabla b)u$; the intermediate values of $r$ follow by complex interpolation. Since $\rho/2<1$, we obtain
  \begin{align}
    \label{eq:fractional-b-Hq}
    \langle D\rangle^{\rho/2} b \langle D\rangle^{-\alpha/2}
    = \left( \langle D\rangle^{\rho/2} b \langle D\rangle^{-\rho/2} \right) \langle D\rangle^{-(\alpha-\rho)/2} \in \mathcal B(L^2)
  \end{align}
  since $\rho\leq\alpha$.
  Thus, also the first term in \eqref{eq:fractional-sandwich-decomp}, after sandwiching, is bounded.
  This concludes the proof.

\label{cor:fractional-A-resolvent-V}
  Let $0<\rho\leq\alpha<1$, $\kappa<\kappa_{\rm c}$, and assume $V\in C^\infty(\mathbb{R}^d)$ satisfies \eqref{ass5} for all multi-indices $\beta\in\mathbb{N}_0^d$. Let $H_\kappa=L_\kappa-V$ and $\lambda\in\mathbb{R}$ be such that $H_\kappa+\lambda\geq\delta>0$ for some $\delta>0$. Then, for every $f\in C_c^\infty(0,\infty)$,
  \begin{align}
    \label{eq:fractional-A-resolvent-V}
    \langle A\rangle^\rho (\lambda+H_\kappa)^{-1} V f(L_\kappa) \in\mathcal B(L^2).
  \end{align}

Set $R_\lambda:=(\lambda+H_\kappa)^{-1}$. By Lemma~\ref{lem:commutators-spectral-cutoff}, $R_\lambda\in C^1(A)$. Hence, Lemma~\ref{lem:fractional-A-commutator} with $B=R_\lambda$ yields
  \begin{align}
    \label{eq:fractional-R-comm}
    [\langle A\rangle^\rho,R_\lambda] \in\mathcal B(L^2).
  \end{align}
  Therefore, first on a common core, and then hence by bounded extension,
  \begin{align}
    \label{eq:fractional-resolvent-split}
    \langle A\rangle^\rho R_\lambda V f(L_\kappa)
    = R_\lambda \langle A\rangle^\rho V f(L_\kappa) + [\langle A\rangle^\rho,R_\lambda] V f(L_\kappa).
  \end{align}
  The second term is bounded by \eqref{eq:fractional-R-comm}.
  The first term is
  \begin{align}
    \label{eq:fractional-resolvent-factor}
    R_\lambda\langle A\rangle^\rho V f(L_\kappa)
    & = R_\lambda\langle D\rangle^{\alpha/2} \left( \langle D\rangle^{-\alpha/2} \langle A\rangle^\rho V \langle D\rangle^{-\alpha/2} \right) \langle D\rangle^{\alpha/2} f(L_\kappa).
  \end{align}
  By Lemma~\ref{lem:fractional-A-sandwich}, the middle factor is bounded.
  As $\kappa<\kappa_{\rm c}$, the form domain of $L_\kappa$ is $H^{\alpha/2}(\mathbb{R}^d)$ with equivalent norms. Thus, $\langle D\rangle^{\alpha/2} f(L_\kappa) \in\mathcal B(L^2)$. Moreover, since $V$ is bounded, $H_\kappa$ also has form domain $H^{\alpha/2}(\mathbb{R}^d)$ and hence, $R_\lambda\langle D\rangle^{\alpha/2} \in\mathcal B(L^2)$. Thus, every factor on the right-hand side of \eqref{eq:fractional-resolvent-factor} is bounded, as claimed.

\label{definitionskibsted}
  Given $\beta,\alpha\geq0$ and $\varepsilon>0$, let $\mathcal{F}_{\beta,\alpha,\varepsilon}$ denote the set of functions $g,g(x,\tau)=g_{\beta,\alpha,\varepsilon}(x,\tau) = -\tau^{-\beta} (-x)^\alpha \chi(\frac{x}{\tau})$, defined for $(x,\tau)\in\mathbb{R}\times\mathbb{R}_+$ and for $\chi\in C^\infty(\mathbb{R})$ with the properties
  \begin{align*}
    \chi(x) = 1 \quad \text{for} \ x < -2 \varepsilon, \qquad \chi(x)=0 \quad \text{for} \ x > -\varepsilon, \\
    \frac{d}{dx}\chi(x) \leq 0 \quad \text{and} \quad \alpha\chi(x) + x \frac{d}{dx}\chi(x) = \tilde\chi(x)^2
  \end{align*}
  where $\tilde\chi(x)\geq0$ and $\tilde\chi \in C^\infty(\mathbb{R})$.

\label{skibstedcor1}
  Suppose Assumption~\ref{assumskibsted} and in addition
  \begin{align}
    \label{eq:skibstedcor1_1}
    & k_0+\alpha_0+\frac32 < \beta_0+n_0, \\
    \label{eq:skibstedcor1_2}
    & k_0+\alpha_0'+\frac32 < n_0 \quad \text{(if $\alpha_0>1$)}, \\
    \label{eq:skibstedcor1_3}
    & \frac{\alpha_0}{2} + 2 < n_0+\beta_0, \\
    \label{eq:skibstedcor1_4}
    & \frac{\alpha_0'}{2}+2 \leq n_0 \quad \text{(implied by \eqref{eq:skibstedcor1_2})}.
  \end{align}
  Then for $(\beta,\alpha)=(0,1),...,(0,\alpha_0'),(\beta_0,\alpha_0)$, any $\varepsilon>0$, $g(x,\tau)\in\mathcal{F}_{\beta,\alpha,\varepsilon}$ and $\theta\in[0,1]$,
  \begin{align}
    (-g_{0,\alpha(1-\theta),\varepsilon}(A(\tau),\tau))^{1/2}\mathrm{e}^{-i t H}f(H)B^{-\alpha/2} = \mathcal{O}(\tau^{(\beta-\alpha\theta)/2}) \quad \text{in $\mathcal{B}(\mathcal{H})$ for $\tau\to\infty$.}
  \end{align}

Theorem~\ref{the6} follows from Proposition~\ref{skibstedcor1} once we verify its assumptions.
  Let us begin with two reductions.
  First, it suffices to prove the theorem where the step function in the statement of Theorem~\ref{the6} is replaced with a smoothed step function of slightly larger support. To prove the estimate with this smoothed step function, we apply Proposition~\ref{skibstedcor1} and Remark~\ref{skibstedremark}.
  Second, it suffices to prove Theorem~\ref{the6} for $\nu\in\mathbb{N}$. Once we have achieved this, \eqref{eq_the6_1} holds for every real $1\leq \nu' \leq \nu$ by complex interpolation with the family $\mathbf{1}(\frac{A}{t}\leq\theta)f(H_\kappa)\mathrm{e}^{-itH_\kappa}\langle A\rangle^{-\nu z}$ with $0\leq\operatorname{Re}(z)\leq1$, noting that $\|\mathbf{1}(\frac{A}{t}\leq\theta)f(H_\kappa)\mathrm{e}^{-itH_\kappa}\|\lesssim1$.

  \smallskip
  Let $\varepsilon>0$ and $\chi\in C^\infty(\mathbb{R};[0,1])$ be a nonincreasing function which satisfies
  \begin{align*}
    \chi(s)=
    \begin{cases}
      1 & \mbox{if} \quad s<-\frac{3}{2}\varepsilon, \\
      0 & \mbox{if} \quad s>-\varepsilon,
    \end{cases}
  \end{align*}
  and $\gamma\chi(s)+s\chi'(s)=\psi(s)^2$ where $0\leq\psi\in C^\infty(\mathbb{R})$ and $\gamma>0$.
  Let $t_0>0$ be fixed, $\tau=t+t_0$, and define $A(\tau)=A-3\varepsilon\tau$.
  We will prove the desired estimate with $\chi(A(\tau)/\tau)$.
  All iterated commutators required in Assumption~\ref{assumskibsted} are first computed on $\mathcal{D}(L_\kappa)\cap\mathcal{D}(A)$. Below we show that $\mathcal{D}(H_\kappa)\cap\mathcal{D}(A)$ is dense in $\mathcal{D}(H_\kappa)$. Hence, the iterated commutators occuring in Assumption~\ref{assumskibsted} extend continuously to $\mathcal{D}(H_\kappa)$, uniformly for $\tau\geq t_0$.

  To verify Assumption~\ref{assumskibsted}, we note the following:
  \begin{enumerate}
  \item[(i)] ${\rm ad}_{A(\tau)}^n(L_\kappa)=(-i\alpha)^n L_\kappa$.

  \item[(ii)] ${\rm ad}_{A(\tau)}^n(V)$ is the bounded multiplication operator obtained from $(x\cdot\nabla)^n V$ (up to corresponding powers of $i$), which is bounded and vanishes as $|x|\to\infty$ uniformly in $\tau\geq t_0$.

  \item[(iii)] ${\rm ad}^{0}_{A(\tau)}(d_\tau A(\tau))=-3\varepsilon$ and ${\rm ad}^{n}_{A(\tau)}(d_\tau A(\tau))=0$ for $n\geq1$.
  \end{enumerate}

  We now verify Assumption~\ref{assumskibsted} with Skibsted's parameters $(\alpha,\beta,\theta)$ in Definition~\ref{definitionskibsted}, Assumption~\ref{assumskibsted}, and Proposition~\ref{skibstedcor1} being denoted by $(\alpha,\beta,\theta)=(\gamma,\beta,\omega)$. We will take $\gamma=2\nu$, $\beta=0$, and $\omega=1$ here.
  We also take $k_0=1/4, \beta_0=1, \alpha_0=2\nu+1/4, n_0=2\nu+2$. Then $\alpha_0'=2\nu$ and \eqref{eq:skibstedcor1_1}--\eqref{eq:skibstedcor1_4} are satisfied.
  Moreover, we take Skibsted's $B=\langle A(t_0)\rangle \sim \langle A\rangle$ and $H=H_\kappa$.

  \smallskip
  First, we verify that $\mathcal{D}(H_\kappa)\cap\mathcal{D}(A)$ is dense in $\mathcal{D}(H_\kappa)$. Indeed, since $\mathrm{e}^{isA}L_\kappa\mathrm{e}^{-isA}=\mathrm{e}^{-\alpha s}L_\kappa$ and $V$ is bounded, we have $\mathrm{e}^{isA}\mathcal{D}(H_\kappa)=\mathcal{D}(H_\kappa)$ and $s\mapsto H_\kappa\mathrm{e}^{isA}u$ is strongly continuous for $u\in\mathcal{D}(H_\kappa)$. Now mollify $u$ by considering $u_\delta=\int\delta^{-1}\eta(s/\delta)\mathrm{e}^{isA}u\,ds$, where $\delta>0$ and $\eta\in C_c^\infty$ with $\int_\mathbb{R}\eta(s)\,ds=1$. Then $u_\delta\in \mathcal{D}(H_\kappa)\cap\mathcal{D}(A)$ and $u_\delta\to u$ as $\delta\to0$ in the graph norm of $H_\kappa$. This shows the density assumption. We now proceed with verifying Items~(1)--(6) from Assumption~\ref{assumskibsted}.

  \begin{enumerate}
  \item First,
    \begin{equation}
      \label{eq_the6_2}
      i[H_\kappa,A]
      = i[L_\kappa,A] - i[V,A]
      = \alpha L_\kappa + x \cdot \nabla_x V
    \end{equation}
    holds on $\mathcal{D}(A)\cap\mathcal{D}(L_\kappa)$ and is extended to a symmetric operator on $\mathcal{D}(L_\kappa)$ by Lemma~\ref{lem5}. Therefore, $i^n {\rm ad}_{A(\tau)}^n(H_\kappa)$ also extends to a symmetric operator on $\mathcal{D}(L_\kappa)$ and $i^n {\rm ad}_{A(\tau)}^n(H_\kappa)\langle H_\kappa\rangle^{-1}$ is uniformly bounded in $\tau \geq t_0$ for all $n\in\mathbb{N}$.

  \item On $\mathcal{D}(L_\kappa)$, we have $L_\kappa\mathrm{e}^{isA}=\mathrm{e}^{\alpha s}\mathrm{e}^{isA}L_\kappa$. Hence,
    \begin{equation}
      \label{eq_the6_3}
      \|H_\kappa \mathrm{e}^{i A(\tau) s}\varphi\|
      \leq \mathrm{e}^{\alpha s}  \|L_\kappa\varphi\| + \|V\|_\infty\|\varphi\|
    \end{equation}
    for all $|s|\leq1$ and $\tau\geq t_0$ and $\varphi\in\mathcal{D}(L_\kappa)$ since the scalar part of $\mathrm{e}^{iA(\tau)s}$ only contributes a phase.

  \item This is trivially satisfied.

  \item This follows from the above notes (i)--(iii).

  \item All the items (5)(a,b,c) follow from the above notes (i)--(iii).

  \item We verify Assumption~\ref{assumskibsted}(6) using Remark~\ref{skibstedremark}. Recall
    \begin{align}
      \label{eq:the6-mourre-decomposition}
      i[H_\kappa,A] = \alpha L_\kappa + x\cdot\nabla V = \alpha H_\kappa+K,
      \quad K := \alpha V + x \cdot \nabla V.
    \end{align}
    By our assumptions on $V$, the function $K$ is bounded and tends to zero as $|x|\to\infty$. In particular, $K\langle D\rangle^{-\alpha/2}$ is compact on $L^2(\mathbb{R}^d)$. Moreover, if $J\subset\subset(0,\infty)$ is a bounded interval compactly contained in $(0,\infty)$, then $\langle D\rangle^{\alpha/2}E_J(H_\kappa)$ is bounded, since $\kappa<\kappa_{\rm c}$, $V\in L^\infty$, and the form domain of $H_\kappa$ is $H^{\alpha/2}(\mathbb{R}^d)$ with equivalent norms. Hence,
    \begin{align}
      \label{eq:the6-compact-K}
      K E_J(H_\kappa)\quad\text{and}\quad
      E_J(H_\kappa)K E_J(H_\kappa)
      \quad\text{ are compact.}
    \end{align}    
    We next prove a strict Mourre estimate locally at every $\lambda\in\operatorname{supp} f$. Fix such a $\lambda$. By assumption, $\lambda\notin\sigma_{\rm p}(H_\kappa)$, so $E_{\{\lambda\}}(H_\kappa)=0$. For $\delta>0$, let $I_\delta = (\lambda-\delta,\lambda+\delta)$. Taking $\delta>0$ small enough that $I_\delta\subset\subset(0,\infty)$, we have
    $$
    \operatorname*{s-lim}_{\delta\searrow0} E_{I_\delta}(H_\kappa) = E_{\{\lambda\}}(H_\kappa) = 0.
    $$
    It follows from \eqref{eq:the6-compact-K} and compactness that
    \begin{align}
      \label{eq:the6-K-small}
      \lim_{\delta\searrow0}\| E_{I_\delta}(H_\kappa) K E_{I_\delta}(H_\kappa) \| = 0.
    \end{align}
    Choose $\delta_\lambda>0$ so small that $\delta_\lambda<\frac{\lambda}{4}$ and
    $$
    \left\| E_{I_{\delta_\lambda}}(H_\kappa) K E_{I_{\delta_\lambda}}(H_\kappa) \right\|
    \leq \frac{\alpha\lambda}{4}.
    $$
    Then, using \eqref{eq:the6-mourre-decomposition}, we obtain the following strict Mourre estimate
    \begin{align}
      \label{eq:the6-local-strict-mourre}
      \begin{split}
        E_{I_{\delta_\lambda}}(H_\kappa) i[H_\kappa,A] E_{I_{\delta_\lambda}}(H_\kappa)
        & = \alpha E_{I_{\delta_\lambda}}(H_\kappa) H_\kappa E_{I_{\delta_\lambda}}(H_\kappa) + E_{I_{\delta_\lambda}}(H_\kappa) K E_{I_{\delta_\lambda}}(H_\kappa) \\
        & \geq \left( \alpha(\lambda-\delta_\lambda) - \frac{\alpha\lambda}{4} \right) E_{I_{\delta_\lambda}}(H_\kappa)
          \geq \frac{\alpha\lambda}{2} E_{I_{\delta_\lambda}}(H_\kappa).
      \end{split}
    \end{align}
    Since $\operatorname{supp} f$ is compact, finitely many of the intervals $I_{\delta_\lambda}$ cover $\operatorname{supp} f$. Taking a smooth partition of unity subordinate to this finite covering, we can write
    $$
    f=\sum_{j=1}^N f_j,
    \qquad
    f_j\in C_c^\infty(I_j),
    $$
    where for each $j$ there is $c_j>0$ such that
    \begin{align}
      \label{eq:the6-local-mourre-j}
      E_{I_j}(H_\kappa)i[H_\kappa,A]E_{I_j}(H_\kappa) \geq c_j E_{I_j}(H_\kappa).
    \end{align}
    Since the desired estimate is linear in $f$, it suffices to prove it for each $f_j$. We therefore fix $j$ and, to simplify notation, write $f=f_j$. Choose a real-valued function
    $$
    f_2\in C_c^\infty(I_j),
    \qquad
    f_2=1 \quad\text{on }\operatorname{supp} f,
    $$
    so that $f_2f=f$. By \eqref{eq:the6-local-mourre-j},
    \begin{align}
      \label{eq:the6-f2-mourre}
      f_2(H_\kappa)i[H_\kappa,A]f_2(H_\kappa) \geq c_j f_2(H_\kappa)^2.
    \end{align}
    By our definition $ A(\tau)=A-3\varepsilon\tau$, we have
    $$
    \mathbb D_H A(\tau)
    = i [H_\kappa,A(\tau)] + d_\tau A(\tau)
    = i [H_\kappa,A]-3\varepsilon.
    $$
    Choosing $\varepsilon>0$ sufficiently small that $3\varepsilon<c_j$, we infer from \eqref{eq:the6-f2-mourre} that
    \begin{align}
      \label{eq:the6-positive-heisenberg}
      \begin{split}
        f_2(H_\kappa) \mathbb D_H A(\tau) f_2(H_\kappa)
        & = f_2(H_\kappa)i[H_\kappa,A]f_2(H_\kappa) - 3\varepsilon f_2(H_\kappa)^2 \\
        & \geq (c_j-3\varepsilon)f_2(H_\kappa)^2 \geq0.
      \end{split}
    \end{align}
    We can now apply Remark~\ref{skibstedremark}. For every pair $(\beta,\gamma)$ occurring in Assumption~\ref{assumskibsted}(6), every $g\in\mathcal{F}_{\beta,\gamma,\varepsilon}$, and every $\varphi\in\mathcal{H}$,
    $$
    \zeta(t)
    = \left(g^{(1)}(A(\tau),\tau)\right)^{1/2} \mathrm{e}^{-itH_\kappa} f(H_\kappa)B^{-\gamma/2}\varphi
    $$
    is well-defined, and \eqref{eq:the6-positive-heisenberg} yields
    $$
    \left( \left\langle \zeta(t), f_2(H_\kappa) \mathbb D_H A(\tau) f_2(H_\kappa)\zeta(t) \right\rangle \right)_- = 0.
    $$
    Thus,
    $$
    \int_0^\infty \left( \left\langle \zeta(t), f_2(H_\kappa) \mathbb D_H A(\tau) f_2(H_\kappa)\zeta(t) \right\rangle \right)_-\, dt = 0.
    $$
    Thus, Assumption~\ref{assumskibsted}(6) holds, in fact with constant $C=0$.
  \end{enumerate}

  Thus, from the conclusion of Proposition~\ref{skibstedcor1} with $(\beta,\gamma)=(0,2\nu)$, we obtain
  \begin{align}
    \label{eq:skibsted-result}
    \begin{split}
    \left\|\sqrt{(-A(\tau))^{\gamma(1-\omega)} \chi\left(\frac{A(\tau)}{\tau}\right)} f(H_\kappa) \mathrm{e}^{-i t H_\kappa}\varphi \right\|
      & \lesssim \tau^{-\gamma\omega/2} \|\langle A(t_0)\rangle^{\gamma/2}\varphi\| \\
      & \lesssim t^{-\gamma\omega/2} \|\langle A\rangle^{\gamma/2}\varphi\|
    \end{split}
  \end{align}
  for $\tau \gg 1$ and $0\leq\omega\leq1$.

  We now conclude the proof by passing from the smooth cutoff in Proposition~\ref{skibstedcor1} to the sharp cutoff in \eqref{eq_the6_1}. Recall $\tau=t+t_0$, $A(\tau)=A-3\varepsilon\tau$, and $\chi\in C^\infty(\mathbb{R};[0,1])$ with $\chi(s)=1$ for $s\leq-3\varepsilon/2$. Let $P_t:=\mathbf{1}\left(\frac{A}{t}\leq\varepsilon\right)$. If $a/t\leq\varepsilon$, then, since $\tau>t$, we have $a/\tau-3\varepsilon\leq-2\varepsilon$. Hence, $\chi(a/\tau-3\varepsilon)=1$ on the spectral support of $P_t$. Because both operators are functions of $A$, we have
  \begin{align}
    \label{eq:sharp-smooth-Skibsted}
    P_t = P_t\chi\left(\frac{A(\tau)}{\tau}\right),
    \qquad
    \|P_tu\| \leq \left\| \chi\left(\frac{A(\tau)}{\tau}\right)u \right\|.
  \end{align}
  Applying \eqref{eq:sharp-smooth-Skibsted} to $u=f(H_\kappa)\mathrm{e}^{-itH_\kappa}\varphi$ and using \eqref{eq:skibsted-result} with $(\gamma,\omega)=(2\nu,1)$ yields
  $$
  \left\| \mathbf{1}\left(\frac{A}{t} \leq\varepsilon\right) f(H_\kappa)\mathrm{e}^{-itH_\kappa}\varphi \right\|
  \lesssim t^{-\nu} \|\langle A\rangle^\nu\varphi\|.
  $$
  Thus, \eqref{eq_the6_1} follows with $\theta=\varepsilon$.

\label{lem8}
  Let $d\in\mathbb{N}$, $\alpha\in[1,2]\cap(0,d)$, $\kappa<\kappa_{\rm c}$, and $\rho>0$.
  Assume $V \in L^\infty(\mathbb{R}^d)$ satisfies $|V(x)| \lesssim \langle x\rangle^{-\rho}$.
  Let $z\in\mathbb{C}\setminus\mathbb{R}$ and $\mu\in[0,1]$.
  Then there exists a positive function $Z(z,\mu)$, which grows at most polynomially in $\langle z\rangle$ and $|\operatorname{Im}(z)|^{-1}$, such that
  \begin{align}
    \label{eq_lem8_1}
    \|\langle x\rangle^\mu(z-H_\kappa)^{-1}\langle x\rangle^{-\mu}\|
    & \lesssim Z(z,\mu)
  \end{align}
  holds for $0\leq\mu\leq1$.
  Moreover, this statement also holds for $1<\mu\leq2$ whenever $\alpha\geq1$ if $d\geq3$ and $\alpha>1$ if $d=2$.

We first prove \eqref{eq_lem8_1} for $\mu=1$. We compute
  \begin{align}
    \label{eq_lem8_3}
    \begin{split}
      [x_j,(z-H_\kappa)^{-1}]
      & = (z-H_\kappa)^{-1}[x_j,|D|^\alpha](z-H_\kappa)^{-1} \\
      & = i\, \alpha (z-H_\kappa)^{-1}|D|^{\alpha-2}D_j(z-H_\kappa)^{-1}.
    \end{split}
  \end{align}
  Note that
  \begin{align}
    \label{eq_lem8_4}
    \langle H_\kappa\rangle^{-1}|D|^{\alpha-2}D_j
    = \langle H_\kappa\rangle^{-1}\langle D\rangle^{\alpha/2}\langle D\rangle^{-\alpha/2}|D|^{\alpha-2}D_j \in \mathcal B(L^2)
  \end{align}
  since $\kappa<\kappa_{\rm c}$ and $0\leq\alpha-1\leq\alpha/2$. Thus, together with
  $$
  \left\| (z-H_\kappa)^{-1} \langle H_\kappa\rangle\right\|
  = \sup_{\lambda \in \sigma(H_\kappa)} \frac{\sqrt{1+\lambda^2}}{|\lambda - z|}
  \lesssim \frac{\langle z\rangle}{|\operatorname{Im}(z)|},
  $$
  we have
  \begin{align*}
    \|x_j(z-H_\kappa)^{-1}\langle x\rangle^{-1}\|
    \lesssim |\operatorname{Im}(z)|^{-1} + |\operatorname{Im}(z)|^{-2} \langle z\rangle.
  \end{align*}
  This, and $\langle x\rangle\lesssim1+\sum_{j=1}^d|x_j|$,
  show \eqref{eq_lem8_1} with
  \begin{align*}
    Z(z,1) = |\operatorname{Im}(z)|^{-1} + |\operatorname{Im}(z)|^{-2} \langle z\rangle.
  \end{align*}
  By complex interpolation, \eqref{eq_lem8_1} therefore holds for all $0\leq\mu\leq1$.

  Next, we prove \eqref{eq_lem8_1} for $\mu=2$ with a similar argument.
  We have
  \begin{align}
    \label{eq_lem8_5}
    [x_j^2,(z-H_\kappa)^{-1}]
    = (z-H_\kappa)^{-1}[x_j^2,|D|^\alpha](z-H_\kappa)^{-1},
  \end{align}
  and
  \begin{align}
    \label{eq_lem8_6}
    [x_j^2,|D|^\alpha]
    = i\alpha \left(2|D|^{\alpha-2}D_j x_j + i |D|^{\alpha-2} + i (\alpha-2) |D|^{\alpha-4} D_j^2 \right).
  \end{align}
  Since $(|D|^{\alpha-2}D_j)^2 \leq |D|^{2\alpha-2}$ and $(|D|^{\alpha-4}D_j^2)^2\leq |D|^{2\alpha-4}$, it suffices to consider $|D|^{\alpha-1}x_j+|D|^{\alpha-2}$ instead of \eqref{eq_lem8_6}. Let us write
  \begin{align}
    \begin{split}
      & (z-H_\kappa)^{-1}(|D|^{\alpha-1}x_j+|D|^{\alpha-2})(z-H_\kappa)^{-1}\langle x\rangle^{-1} \\
      & \quad = (z-H_\kappa)^{-1}(|D|^{\alpha-1}x_j\langle x\rangle^{-1}+|D|^{\alpha-2}\langle x\rangle^{-1})\langle x\rangle(z-H_\kappa)^{-1}\langle x\rangle^{-1}.
    \end{split}
  \end{align}
  Since $|D|^{\alpha-2}\langle x\rangle^{-1}=\left(|D|^{\alpha-2}|x|^{\alpha-2}\right) \left(|x|^{2-\alpha}\langle x\rangle^{-1}\right)$ is bounded for $\alpha\geq1$ if $d\geq3$ and $\alpha>1$ if $d=2$ by Hardy's inequality, we have
  \begin{align}
    \label{eq_lem8_7}
    \|(z-H_\kappa)^{-1}(|D|^{\alpha-1}x_j+|D|^{\alpha-2})(z-H_\kappa)^{-1}\langle x\rangle^{-1}\|
    \lesssim \left(|\operatorname{Im}(z)|^{-2}+|\operatorname{Im}(z)|^{-3} \langle z\rangle\right) \langle z\rangle
  \end{align}
  using the bound in the case $\mu=1$.
  By \eqref{eq_lem8_5} and \eqref{eq_lem8_7} we have \eqref{eq_lem8_1} with $\mu=2$ and
  \begin{align}
    \begin{split}
      Z(z,2)
      & = |\operatorname{Im}(z)|^{-1}+|\operatorname{Im}(z)|^{-3}+|\operatorname{Im}(z)|^{-4} \langle z\rangle \\
      & \quad + (|\operatorname{Im}(z)|^{-2} + |\operatorname{Im}(z)|^{-3} \langle z\rangle)\langle z\rangle (|\operatorname{Im}(z)|^{-1} + |\operatorname{Im}(z)|^{-2} \langle z\rangle).
    \end{split}
  \end{align}
  By complex interpolation between $\mu=0$ and $\mu=2$, we obtain \eqref{eq_lem8_1} for all $\mu\in[0,2]$ with $Z(z,\mu) = |\operatorname{Im}(z)|^{\mu/2-1} Z(z,2)^{\mu/2}$.

\label{lem9}
  Let $d\in\mathbb{N}$, $\alpha\in[1,2]\cap(0,d)$, $\kappa<\kappa_{\rm c}$, $\rho>0$, $\mu\in[0,1]$, and $f\in C_c^\infty(0,\infty)$.
  Assume $V \in L^\infty(\mathbb{R}^d:\mathbb{R})$ satisfies $|V(x)| \lesssim \langle x\rangle^{-\rho}$.
  Then,
  \begin{equation}
    \label{eq_lem9_1}
    \|\langle x\rangle^\mu f(H_\kappa) \mathrm{e}^{-i t H_\kappa}\langle x\rangle^{-\mu}\|
    \lesssim \langle t\rangle^\mu, \quad t\in\mathbb{R}.
  \end{equation}
  Moreover, \eqref{eq_lem9_1} also holds for $1<\mu\leq2$ for all $d\geq3$, or $d=2$ and $\alpha>1$.

We first prove \eqref{eq_lem9_1} when $\mu=1$. By the Helffer--Sj\"ostrand formula \eqref{eq:hs},
  \begin{equation}
    \label{eq_lem9_2}
    [x_j,f(H_\kappa)]
    = \frac{\alpha}{2\pi} \int_{\mathbb{C}}\bar{\partial} \tilde{f}(z)(z-H_\kappa)^{-1}|D|^{\alpha-2}D_j(z-H_\kappa)^{-1} \, dz \wedge d\bar{z}.
  \end{equation}
  Note that
  \begin{equation}
    \label{eq_lem9_3}
    x_j \mathrm{e}^{-i t H_\kappa}
    = \mathrm{e}^{-i t H_\kappa}x_j + \alpha\int_0^t \mathrm{e}^{-i(t-s) H_\kappa} |D|^{\alpha-2} D_j \mathrm{e}^{-i s H_\kappa} \, ds.
  \end{equation}
  Therefore,
  \begin{equation}
    \label{eq_lem9_5}
    \|x_jf(H_\kappa) \mathrm{e}^{-i t H_\kappa}\langle x\rangle^{-1}\|
    \leq \|f(H_\kappa) x_j \mathrm{e}^{-i t H_\kappa}\langle x\rangle^{-1}\| + \|[x_j,f(H_\kappa)] \mathrm{e}^{-i t H_\kappa}\|
    \lesssim \langle t\rangle
  \end{equation}
  follows from \eqref{eq_lem8_4}, \eqref{eq_lem9_3}, and $\langle x\rangle\lesssim1+\sum_{j=1}^d|x_j|$. By complex interpolation between $\mu=0$ and $\mu=1$, we have \eqref{eq_lem9_1} for all $0\leq\mu\leq1$.

  Next, we prove \eqref{eq_lem9_1} when $\mu=2$. It suffices to prove
  \begin{equation}
    \label{eq_lem9_6}
    \|x_j^2 f(H_\kappa) \mathrm{e}^{-i t H_\kappa}g(H_\kappa)\langle x\rangle^{-2}\|
    \lesssim \langle t\rangle^2
  \end{equation}
  for $g\in C_c^\infty(0,\infty)$ such that $f = f g$. We have
  \begin{align}
    \label{eq_lem9_10}
    \begin{split}
      [x_j^2,f(H_\kappa)]
      & = \frac{\alpha}{2\pi}\int_{\mathbb{C}}\bar{\partial} \tilde{f}(z)(z-H_\kappa)^{-1}\left\{2|D|^{\alpha-2}D_jx_j\right. \\
      & \qquad\qquad \left. + i |D|^{\alpha-2} + (\alpha-2)\, i|D|^{\alpha-4}D_j^2\right\}(z-H_\kappa)^{-1} \, dz \wedge d\bar{z}.
    \end{split}
  \end{align}
  Since
  \begin{align*}
    \|[(z-H_\kappa)^{-1},x_j]\|
    & = \alpha\|(z-H_\kappa)^{-1}|D|^{\alpha-2}D_j(z-H_\kappa)^{-1}\| \\
    & \lesssim |\operatorname{Im}(z)|^{-2} \langle z\rangle,
    \quad z \in \operatorname{supp}(\tilde f)
  \end{align*}
  by \eqref{eq_lem8_3} and \eqref{eq_lem8_4}, we have
  \begin{align}
    \label{eq_lem9_7}
    \begin{split}
      & \||D|^{\alpha-2}D_j x_j(z-H_\kappa)^{-1}g(H_\kappa) \mathrm{e}^{-i t H_\kappa}\langle x\rangle^{-1}\| \\
      & \quad \lesssim \langle t\rangle |\operatorname{Im}(z)|^{-1} \langle z\rangle
        + |\operatorname{Im}(z)|^{-2} \langle z\rangle, \quad z\in\operatorname{supp}(\tilde f)
    \end{split}
  \end{align}
  using $\|D_j|D|^{-1}\|\leq1$, \eqref{eq_lem8_4}, and \eqref{eq_lem9_5}. We now consider the second and third summand in \eqref{eq_lem9_10}; for the third summand, we use $\|D_j^2|D|^{-2}\|\leq1$. We have
  \begin{align}
    \label{eq_lem9_8}
    \begin{split}
      & \||D|^{\alpha-2}(z-H_\kappa)^{-1}g(H_\kappa) \mathrm{e}^{-i t H_\kappa}\langle x\rangle^{\alpha-2}\| \\
      & \quad \lesssim \||D|^{\alpha-2}|x|^{\alpha-2}\|\|\langle x\rangle^{2-\alpha}(z-H_\kappa)^{-1}\langle x\rangle^{\alpha-2}\| \|\langle x\rangle^{2-\alpha}g(H_\kappa) \mathrm{e}^{-i t H_\kappa}\langle x\rangle^{\alpha-2}\| \\
      & \quad \lesssim Z(z,2-\alpha) \langle t\rangle^{2-\alpha}
    \end{split}
  \end{align}
  by $|x|^{\alpha-2}\langle D\rangle^{\alpha-2}\lesssim1$, Lemmas~\ref{lem8} and~\eqref{eq_lem9_1} with $\mu=2-\alpha$. By \eqref{eq_lem9_7} and \eqref{eq_lem9_8},
  \begin{equation}
    \label{eq_lem9_9}
    \|[x_j^2,f(H_\kappa)] \mathrm{e}^{-i t H_\kappa}g(H_\kappa)\langle x\rangle^{-1}\|
    \lesssim \langle t\rangle,
  \end{equation}
  where we used that $\tilde f$ is compactly supported and can be chosen of sufficiently high order to compensate the inverse powers of $|\operatorname{Im}(z)|$. In particular,
  \begin{equation}
    \label{eq_lem9_11}
    \|\langle x\rangle^2f(H_\kappa)\langle x\rangle^{-2}\| \lesssim 1
  \end{equation}
  by applying the Helffer--Sj\"ostrand formula to $f(H_\kappa)$ and using Lemma~\ref{lem8} to control $\langle x\rangle^2(z-H_\kappa)^{-1}\langle x\rangle^{-2}$ in the resulting integrand.
  By \eqref{eq_lem9_9}, to prove \eqref{eq_lem9_6}, it suffices to prove
  \begin{equation}
    \label{eq_lem9_12}
    \|f(H_\kappa) x_j^2 \mathrm{e}^{-i t H_\kappa}g(H_\kappa)\langle x\rangle^{-2}\|
    \lesssim \langle t\rangle^2.
  \end{equation}
  Using \eqref{eq_lem9_3}, we compute
  \begin{align}
    \label{eq_lem9_13}
    \begin{split}
      x_j^2 \mathrm{e}^{-i t H_\kappa}
      & = \mathrm{e}^{-i t H_\kappa}x_j^2 + \alpha \int_0^t \mathrm{e}^{-i (t-s) H_\kappa}|D|^{\alpha-2} D_j \mathrm{e}^{-i s H_\kappa} x_j \, ds \\
      & \quad + \alpha \int_0^t \mathrm{e}^{-i (t-s) H_\kappa} x_j |D|^{\alpha-2} D_j \mathrm{e}^{-i s H_\kappa}\, ds \\
      & \quad + \alpha^2 \int_0^t \int_0^{t-s} \mathrm{e}^{-i (t-s-r) H_\kappa} |D|^{\alpha-2} D_j \mathrm{e}^{-i r H_\kappa} |D|^{\alpha-2} D_j \mathrm{e}^{-i s H_\kappa} \, dr \, ds.
    \end{split}
  \end{align}
  The second summand on the right-hand side of \eqref{eq_lem9_13} contributes $\mathcal O(t)$. Indeed, writing $M_j:=|D|^{\alpha-2}D_j$, we see
  \begin{align}
    \label{eq:spectral-Mj-bounds}
    f(H_\kappa)M_j, \quad M_j f(H_\kappa)\in\mathcal B(L^2).
  \end{align}
  by inserting $1=\langle H_\kappa\rangle\langle H_\kappa\rangle^{-1}$ and using \eqref{eq_lem8_4}. Hence, we also have
  $$
  f(H_\kappa)\mathrm{e}^{-i(t-s)H_\kappa} M_j
  = \left(f(H_\kappa)\langle H_\kappa\rangle \, \mathrm{e}^{-i(t-s)H_\kappa}\right) \left(\langle H_\kappa\rangle^{-1} M_j\right) \in \mathcal B(L^2).
  $$
  Furthermore,
  $$
  x_j g(H_\kappa)\langle x\rangle^{-2}
  = g(H_\kappa) x_j \langle x\rangle^{-2} + [x_j,g(H_\kappa)]\langle x\rangle^{-2} \in \mathcal B(L^2).
  $$
  The boundedness is clear for the first summand; to see this for the second summand, one may write $[x_j,g(H_\kappa)]$ as in \eqref{eq_lem9_2} in terms of the Helffer--Sj\"ostrand formula and then use that the operator norm of
  $$
  (H_\kappa-z)^{-1}M_j(H_\kappa-z)^{-1}
  = \left((H_\kappa-z)^{-1}\langle H_\kappa\rangle\right) \left(\langle H_\kappa\rangle^{-1} M_j\right) (H_\kappa-z)^{-1}
  $$
  is bounded (by \eqref{eq_lem8_4}) by a function which is integrable against a suitable almost-analytic extension of $g$.
  By a similar argument, the contribution from the double-integral in the last line of \eqref{eq_lem9_13} is $\mathcal O(t^2)$. Indeed, by using the spectral localizations and \eqref{eq:spectral-Mj-bounds},
  \begin{align*}
    & \left\| f(H_\kappa)\mathrm{e}^{-i(t-s-r)H_\kappa} M_j \mathrm{e}^{-irH_\kappa} M_j \mathrm{e}^{-isH_\kappa} g(H_\kappa)\langle x\rangle^{-2} \right\| \\
    & \quad = \left\| \mathrm{e}^{-i(t-s-r)H_\kappa} \left(f(H_\kappa)M_j\right) \mathrm{e}^{-irH_\kappa} \left(M_jg(H_\kappa)\right)\mathrm{e}^{-isH_\kappa} \langle x\rangle^{-2} \right\| \lesssim1,
  \end{align*}
  uniformly for $r,s\geq0$. Integration over $\{(s,r):0\leq s\leq t,\ 0\leq r\leq t-s\}$ therefore gives an $\mathcal O(t^2)$ contribution.




  It remains to estimate the third single integral in \eqref{eq_lem9_13}. We use $x_jM_j=M_jx_j+[x_j,M_j]$, where
  \begin{align}
    \label{eq:xj-Mj-comm-repair}
    [x_j,M_j] = i|D|^{\alpha-2} + (\alpha-2)i|D|^{\alpha-4}D_j^2.
  \end{align}
  For the first term we obtain, using \eqref{eq:spectral-Mj-bounds} and the already proved $\mu=1$ case,
  \begin{align*}
    \left\| f(H_\kappa)M_jx_j \mathrm{e}^{-isH_\kappa} g(H_\kappa)\langle x\rangle^{-2} \right\|
    \lesssim \left\| x_j g(H_\kappa)\mathrm{e}^{-isH_\kappa}\langle x\rangle^{-1}\right\|
    \lesssim \langle s\rangle.
  \end{align*}
  We treat the commutator term next. To this end, let $\beta=2-\alpha$. Then both summands in \eqref{eq:xj-Mj-comm-repair} are of the form $Q|D|^{-\beta}$ with $Q\in\mathcal B(L^2)$ being a bounded Fourier multiplier. By $|D|^{-\beta}\langle x\rangle^{-\beta}\in\mathcal B(L^2)$ and the already proved weighted propagation estimate with $\mu=\beta\leq1$,
  \begin{align*}
    \left\| |D|^{-\beta}g(H_\kappa)\mathrm{e}^{-isH_\kappa} \langle x\rangle^{-2} \right\| 
    & \leq \left\| |D|^{-\beta}\langle x\rangle^{-\beta}\right\| \left\| \langle x\rangle^\beta g(H_\kappa)\mathrm{e}^{-isH_\kappa} \langle x\rangle^{-\beta} \right\| \left\| \langle x\rangle^{\beta-2}\right\|_\infty \\
    & \lesssim \langle s\rangle^\beta \lesssim \langle s\rangle.
  \end{align*}
  Thus, the integrand of the third term in \eqref{eq_lem9_13} is $\mathcal O(\langle s\rangle)$, and hence the third term contributes $\mathcal O(t^2)$. Together with the previous estimates, this proves \eqref{eq_lem9_12} and thus~\eqref{eq_lem9_6}.

  Finally, by complex interpolation between $\mu=0$ and $\mu=2$, we obtain \eqref{eq_lem9_1} for all $0\leq\mu\leq2$.

\label{lem9-small-alpha}
  Let $d\in\mathbb{N}$, $\alpha\in(1/2,1)\cap(0,d)$, $\kappa\leq\kappa_{\rm c}$, and let $f\in C_c^\infty(0,\infty)$. Then,
  \begin{align}
    \label{eq:lem9-small-alpha}
    \left\| \langle x\rangle^\mu f(L_\kappa)e^{-itL_\kappa} \langle x\rangle^{-\mu} \right\|
    \lesssim_f \langle t\rangle^\mu, \quad 0\leq\mu\leq1.
  \end{align}
  The same conclusion holds for $\alpha=1/2$ provided $d\geq2$.

We divide the proof into four steps.

  \medskip
  \noindent
  {\bf Step 1: Localization of the velocity.}
  Set $\beta:=1-\alpha\in(0,1/2)$ and
  $$
  s_\alpha:=\frac{2\beta}{\alpha}=\frac{2(1-\alpha)}{\alpha}.
  $$
  Since $\alpha>1/2$, we have $0<s_\alpha<2$. Moreover, $s_\alpha<\frac d\alpha$, which is automatic since $\alpha>1/2$ and $d\geq1$. We now apply Proposition~\ref{eqsob}(2) to $V(x)=\kappa/|x|^\alpha$. Since $L_0^{s_\alpha/2}=|D|^{\alpha s_\alpha/2}=|D|^\beta$, Proposition~\ref{eqsob}(2), implies that $|D|^{-\beta} L_\kappa^{s_\alpha/2}\in\mathcal B(L^2)$.

  Let $h\in C_c^\infty(0,\infty)$. Since $L_\kappa^{-s_\alpha/2}h(L_\kappa) \in\mathcal B(L^2)$ by the spectral theorem, we obtain
  \begin{align}
    \label{eq:negative-sobolev-spectral}
    |D|^{-\beta}h(L_\kappa)
    = (|D|^{-\beta}L_\kappa^{s_\alpha/2})\, (L_\kappa^{-s_\alpha/2}h(L_\kappa)) \in\mathcal B(L^2).
  \end{align}
  Introduce $\alpha^{-1}$ times the $j$-th component of the velocity,
  \begin{align}
    v_j := |D|^{\alpha-2}D_j = \frac{D_j}{|D|}\,|D|^{-\beta}.
  \end{align}
  Since $D_j/|D|$ is bounded on $L^2$,
  \begin{align}
    \label{eq:localized-velocity-left}
    h(L_\kappa)v_j\in\mathcal B(L^2).
  \end{align}
  At the endpoint $\alpha=1/2$, one has $s_\alpha=2$. Proposition~\ref{eqsob}(2) is still applicable provided $2<d/\alpha=2d$, i.e., $d\geq2$. Thus, \eqref{eq:negative-sobolev-spectral}--\eqref{eq:localized-velocity-left} remain valid in that case. It is in this step where we need the assumption $\alpha\geq1/2$.

  \medskip
  \noindent
  {\bf Step 2: Local $C^1(x_j)$ regularity of $h(L_\kappa)$.}
  We show that, for every $j\in\{1,2,...,d\}$ and $h\in C_c^\infty(0,\infty)$, one has
  \begin{align}
    \label{eq:hL-C1-x}
    h(L_\kappa)\mathcal D(x_j)\subset\mathcal D(x_j),
    \qquad
    [x_j,h(L_\kappa)]\in\mathcal B(L^2).
  \end{align}
  To this end, let
  $$
  U_j(\tau):=\mathrm{e}^{i\tau x_j},
  \qquad
  B_{j,\tau}:=\frac{U_j(\tau)-1}{\tau},
  \qquad
  0<|\tau|\leq1.
  $$
  We first prove
  \begin{align}
    \label{eq:uniform-difference-comm}
    \sup_{0<|\tau|\leq1} \|[B_{j,\tau},h(L_\kappa)]\|<\infty,
  \end{align}
  which eventually allows us to pass to the limit $\tau\to0$. To prove \eqref{eq:uniform-difference-comm}, first note that
  \begin{align*}
    U_j(\tau) \frac{\kappa}{|x|^\alpha} U_j(\tau)^* & = \frac{\kappa}{|x|^\alpha}, \\
    U_j(\tau)|D|^\alpha U_j(\tau)^* & = |D-\tau e_j|^\alpha,
  \end{align*}
  where $e_j$ denotes the $j$-th canonical basis vector in $\mathbb{R}^d$.
  Since $0<\alpha<1$,
  $$
  \left| |\xi-\tau e_j|^\alpha-|\xi|^\alpha \right| \leq |\tau|^\alpha.
  $$
  Hence,
  $$
  U_j(\tau)L_\kappa U_j(\tau)^*-L_\kappa \text{ is bounded for every fixed $\tau$.}
  $$
  In particular, $U_j(\tau)$ preserves $\mathcal D(L_\kappa)$ and the usual resolvent commutator identity may be used with $B_{j,\tau}$. To write it, define
  \begin{align}
    q_\tau^-(\xi) & := \frac{|\xi-\tau e_j|^\alpha-|\xi|^\alpha}{\tau}, \\
    q_\tau^+(\xi) & := \frac{|\xi|^\alpha-|\xi+\tau e_j|^\alpha}{\tau}.
  \end{align}
  Then,
  \begin{align}
    \label{eq:Btau-L-two-forms}
    [B_{j,\tau},L_\kappa] = q_\tau^-(D)U_j(\tau) = U_j(\tau)q_\tau^+(D).
  \end{align}
  We claim that
  \begin{align}
    \label{eq:q-tau-bound}
    |q_\tau^\pm(\xi)| \lesssim |\xi|^{\alpha-1} = |\xi|^{-\beta}, \quad \xi\neq0, \quad 0<|\tau|\leq1,
  \end{align}
  uniformly in $\tau$.
  Indeed, if $|\xi|\geq2|\tau|$, the mean value theorem gives
  $$
  \left| |\xi-\tau e_j|^\alpha-|\xi|^\alpha \right|
  \lesssim |\tau|\,|\xi|^{\alpha-1}.
  $$
  If $|\xi|<2|\tau|$, then, since $\alpha<1$,
  $$
  \left| |\xi-\tau e_j|^\alpha-|\xi|^\alpha \right|
  \lesssim |\tau|^\alpha
  \lesssim |\tau|\,|\xi|^{\alpha-1}.
  $$
  Thus, there are uniformly bounded Fourier multipliers $m_\tau^\pm(D)$ such that
  \begin{align}
    \label{eq:q-factor}
    q_\tau^\pm(D) = m_\tau^\pm(D)|D|^{-\beta},
    \qquad  \sup_{0<|\tau|\leq1}\|m_\tau^\pm(D)\|<\infty.
  \end{align}
  By \eqref{eq:negative-sobolev-spectral}, for every $a\in C_c^\infty(0,\infty)$,
  \begin{align}
    \label{eq:q-spectral-localized}
    \sup_{0<|\tau|\leq1} \left( \|q_\tau^\pm(D)a(L_\kappa)\| + \|a(L_\kappa)q_\tau^\pm(D)\| \right) <\infty.
  \end{align}
  Choose a real-valued $g\in C_c^\infty(0,\infty)$ such that $g=1$ on a neighborhood of $\operatorname{supp} h$. Thus, $h(L_\kappa)=g(L_\kappa)h(L_\kappa)$. Since for every $\tau\neq0$, $B_{j,\tau}$ is bounded,
  \begin{align}
    \label{eq:difference-product-decomp}
    [B_{j,\tau},h(L_\kappa)]
    = g(L_\kappa)[B_{j,\tau},h(L_\kappa)] + [B_{j,\tau},g(L_\kappa)]h(L_\kappa).
  \end{align}
  Write
  $$
  R(z):=(z-L_\kappa)^{-1}.
  $$
  By the Helffer--Sj\"ostrand formula \eqref{eq:hs},
  \begin{align}
    \label{eq:local-C1-first}
    g(L_\kappa)[B_{j,\tau},h(L_\kappa)]
    & = \frac{1}{2\pi i} \int_{\mathbb{C}} \overline\partial\widetilde h(z)\, g(L_\kappa)R(z) [B_{j,\tau},L_\kappa] R(z)\, dz\wedge d\overline z.
  \end{align}
  Using the first representation of $[B_{j,\tau},L_\kappa]$ in \eqref{eq:Btau-L-two-forms} shows that the integrand equals $\overline\partial\widetilde h(z)\, R(z)g(L_\kappa) q_\tau^-(D) U_j(\tau) R(z)$. By \eqref{eq:q-spectral-localized},
  $$
  \left\| g(L_\kappa)R(z) [B_{j,\tau},L_\kappa]R(z) \right\|
  \lesssim |\operatorname{Im} z|^{-2},
  $$
  uniformly in $\tau$.
  Similarly, using the second representation in \eqref{eq:Btau-L-two-forms},
  \begin{align}
    \label{eq:local-C1-second}
    [B_{j,\tau},g(L_\kappa)]h(L_\kappa)
    & = \frac{1}{2\pi i} \int_{\mathbb{C}} \overline\partial\widetilde g(z)\, R(z)[B_{j,\tau},L_\kappa] R(z)h(L_\kappa)\, dz\wedge d\overline z.
  \end{align}
  Similarly as above, we get, uniformly in $\tau$,
  $$
  \left\| R(z)[B_{j,\tau},L_\kappa] R(z)h(L_\kappa) \right\| \lesssim |\operatorname{Im} z|^{-2}.
  $$
  Choosing the almost analytic extensions of high enough order, the two Helffer--Sj\"ostrand integrals are absolutely convergent in operator norm. Thus, \eqref{eq:difference-product-decomp} gives \eqref{eq:uniform-difference-comm}.

  \smallskip
  We now pass from bounded difference quotients to the commutator with $x_j$. Let $u,v\in\mathcal D(x_j)$. Since
  $$
  B_{j,\tau}v \to i x_jv
  \quad \text{and} \quad
  B_{j,\tau}^*u \to -i x_ju
  \quad \text{as }\tau\to0,
  $$
  the forms associated with $[B_{j,\tau},h(L_\kappa)]$ converge to the forms associated with $i[x_j,h(L_\kappa)]$. Since the uniform estimate \eqref{eq:uniform-difference-comm} gives
  $$
  |\langle x_ju,h(L_\kappa)v\rangle - \langle h(L_\kappa)^*u,x_jv\rangle|
  \lesssim \|u\| \|v\|,
  $$
  the limiting quadratic commutator form
  $$
  (u,v)\mapsto \langle x_ju,h(L_\kappa)v\rangle - \langle h(L_\kappa)^*u,x_jv\rangle
  $$
  extends continuously from $\mathcal D(x_j)\times\mathcal D(x_j)$ to $L^2\times L^2$.
  Denote the corresponding bounded operator by $C_h$. If $v\in\mathcal{D}(x_j)$, then for every $u\in\mathcal{D}(x_j)$,
  $$
  \langle x_ju,h(L_\kappa)v\rangle = \langle h(L_\kappa)^*u,x_jv\rangle + \langle u,C_hv\rangle
  $$
  The right-hand side is bounded by $C_v\|u\|$. Since $x_j$ is selfadjoint, this implies $h(L_\kappa)v\in\mathcal D(x_j)$. Moreover, $[x_j,h(L_\kappa)]=C_h$ as a bounded operator. This proves \eqref{eq:hL-C1-x}.

  \medskip
  \noindent
  {\bf Step 3: Conclusion of \eqref{eq:lem9-small-alpha} with $\mu=1$.}
  Choose $g\in C_c^\infty((0,\infty);\mathbb{R})$ such that $g=1$ on a neighborhood of $\operatorname{supp} f$, and define the bounded selfadjoint operator
  $$
  K := k(L_\kappa),
  \qquad
  k(\lambda) := \lambda g(\lambda).
  $$
  By Step~2,
  $$
  K\in C^1(x_j),
  \qquad
  [x_j,K]\in\mathcal B(L^2).
  $$
  Hence,
  \begin{align}
    \label{eq:bounded-K-Duhamel}
    [x_j,\mathrm{e}^{-itK}] = -i\int_0^t \mathrm{e}^{-i(t-s)K} [x_j,K] \mathrm{e}^{-isK}\,ds,
  \end{align}
  and therefore
  \begin{align}
    \label{eq:bounded-K-comm-bound}
    \|[x_j,\mathrm{e}^{-itK}]\| \lesssim |t|.
  \end{align}
  Since $k(\lambda)=\lambda$ on $\operatorname{supp} f$, the spectral theorem gives $\mathrm{e}^{-itK}f(L_\kappa) = \mathrm{e}^{-itL_\kappa}f(L_\kappa)$. Thus,
  \begin{align}
    \label{eq:x-weight-small-alpha}
    \begin{split}
      \|x_jf(L_\kappa)\mathrm{e}^{-itL_\kappa} \langle x\rangle^{-1}\|
      & = \|x_j \mathrm{e}^{-itK}f(L_\kappa) \langle x\rangle^{-1}\| \\
      & \leq \|\mathrm{e}^{-itK}x_jf(L_\kappa) \langle x\rangle^{-1}\| + \|[x_j,\mathrm{e}^{-itK}] f(L_\kappa)\langle x\rangle^{-1}\|.
    \end{split}
  \end{align}
  By Step~2, $[x_j,f(L_\kappa)]\in\mathcal B(L^2)$, and hence
  \begin{align}
    x_jf(L_\kappa)\langle x\rangle^{-1}
    = f(L_\kappa)x_j\langle x\rangle^{-1} + [x_j,f(L_\kappa)] \langle x\rangle^{-1}
  \end{align}
  is bounded. Together with \eqref{eq:bounded-K-comm-bound}, this yields
  \begin{align}
    \label{eq:x-weight-small-alpha-final}
    \|x_jf(L_\kappa) \mathrm{e}^{-itL_\kappa} \langle x\rangle^{-1}\|
    \lesssim_f \langle t\rangle.
  \end{align}
  Since $\langle x\rangle \lesssim 1+\sum_{j=1}^d|x_j|$, we conclude \eqref{eq:lem9-small-alpha} with $\mu=1$.

  \medskip
  \noindent
  {\bf Step 4: Interpolation.}
  For fixed $t$, set $T_t := f(L_\kappa) \mathrm{e}^{-itL_\kappa}$. We have $\|T_t\|\leq\|f\|_\infty$. Thus, complex interpolation with \eqref{eq:lem9-small-alpha} with $\mu=1$ yields \eqref{eq:lem9-small-alpha} for all $0\leq\mu\leq1$.

Let $\alpha>1$ and let $T:=C_0(-\Delta)$ with $C_0\in\mathcal{K}_\alpha$. We first verify that the free operator $T$ satisfies the hypotheses on the Fourier multiplier in Theorem~\ref{giere}. We then verify Assumption~\ref{assumheatdifference} for $H_1:=T-V_\kappa$ and $H_2:=T-V_\kappa-V^S$.

  \medskip
  \noindent
  {\bf Step 1: Admissibility of the Fourier multiplier.}
  By the definition of $\mathcal{K}_\alpha$, for every $t>0$ there is a probability density $\sigma_t^{(C_0)}$ on $\mathbb{R}_+$ such that
  $$
  \mathrm{e}^{-tC_0(\lambda)} = \int_0^\infty \mathrm{e}^{-s\lambda}\sigma_t^{(C_0)}(s)\,ds
  \quad\text{with}\quad
  \sigma_t^{(C_0)}(s) \leq\mathrm{e}^{ct}\sigma_t^{(\alpha/2)}(s)
  $$
  for some $c\geq0$.
  In particular, $C_0(0)=0$. Moreover, $\lambda\mapsto\mathrm{e}^{-tC_0(\lambda)}$ is completely monotone for every $t>0$, and therefore $C_0$ is a Bernstein function. In particular,
  \begin{align}
    \label{eq:bernstein-consequence}
    C_0\in C^\infty(0,\infty),
    \quad\text{and}\quad
    C_0'(\lambda)>0
    \quad\text{for all } \lambda>0
  \end{align}
  since $C_0$ is nonconstant.
  Recall also that, by operator monotonicity of the logarithm,
  \begin{align}
    \label{eq:C0-lower-fractional}
    C_0(-\Delta)\geq L_0-c.
  \end{align}
  Set
  $$
  P(\xi):=C_0(|\xi|^2).
  $$
  Then, for $\xi\neq0$, we have $\nabla P(\xi) = 2C_0'(|\xi|^2)\xi$, and hence $\nabla P(\xi)\neq0$.
  Now, for $h(|\xi|):=P(\xi)$, we verify that the set $\{k>0:\, h''(k)=(h'(k))^2\}$ is discrete. To this end, note that $h:(0,\infty)\to(0,\infty)$ is analytic since $C_0$ is a Bernstein function.
  Hence, also $g(k):=h''(k)-(h'(k))^2$ is analytic on $(0,\infty)$. Thus, by the identity theorem for real-analytic functions, the zero set $\{k>0:\, g(k)=0\}$ is either discrete or $g$ vanishes identically. Let us show that $g\not\equiv0$ via a contradiction, i.e., suppose $g\equiv0$. Then, define $f(k):=\mathrm{e}^{-h(k)}$, which obeys the differential equation
  $$
  f''(k) = - \left(h''(k)-(h'(k))^2\right)\mathrm{e}^{-h(k)}.
  $$
  By our assumption, $f''(k)=0$ for all $k>0$, i.e., $f(k)=Ak+B$ for some integration constants $A,B\in\mathbb{R}$. Thus, $h(k)=-\ln\left(Ak+B\right)$ and therefore $C_0(\lambda)=-\ln\left(A\sqrt\lambda +B\right)$.
  But this forces $C_0$ into an impossible form; indeed, for $A<0$ the argument of $C_0$ becomes eventually negative; for $A\geq0$, the function $C_0(\lambda)$ is nonincreasing, which is in contrast to \eqref{eq:bernstein-consequence}.
  We have thus shown $M_1=\emptyset$ and, since $0$ is not an accumulation point of $M_2$, that $M_2=\{k>0:\,g(k)=0\}$ is discrete.
  Thus, $T$ satisfies the assumptions of Theorem~\ref{giere}.

  \medskip
  \noindent
  {\bf Step 2: Heat kernel comparison.}
  Let
  $$
  S_T(t):=\mathrm{e}^{-tT}.
  $$
  By subordination and the defining estimate for $\sigma_t^{(C_0)}$,
  \begin{align}
    \label{eq:massive-free-domination}
    S_T(t)(x,y) \leq \mathrm{e}^{ct}\mathrm{e}^{-tL_0}(x,y).
  \end{align}
  By assumption,
  \begin{align}
    \label{eq:Vkappa-absolute-bound}
    |V_\kappa(x)| \leq C_{\kappa,\tilde\kappa}|x|^{-\alpha}.
  \end{align}
  Thus, by Trotter's formula and \eqref{eq:massive-free-domination},
  \begin{align}
    \label{eq:massive-H1-domination}
    0\leq \mathrm{e}^{-tH_1}(x,y) \lesssim \mathrm{e}^{ct}\mathrm{e}^{-tL_\kappa}(x,y).
  \end{align}
  Notice also that, by \eqref{eq:C0-lower-fractional},
  $$
  H_1 = T-V_\kappa \geq L_0-\frac{\kappa}{|x|^\alpha}-c = L_\kappa-c,
  $$
  so $H_1$ is bounded from below.

  We next consider $H_2=H_1-V^S$, which is also bounded from below since $V^S$ is bounded. Moreover, by \eqref{eq:massive-H1-domination} and Trotter's formula,
  \begin{align}
    \label{eq:massive-H2-domination}
    0 \leq \mathrm{e}^{-tH_2}(x,y) \lesssim \mathrm{e}^{c't}\mathrm{e}^{-tL_\kappa}(x,y).
  \end{align}

  \medskip
  \noindent
  {\bf Step 3: On $W(H_1,T)$.}
  We verify the assumptions of Theorem~\ref{giere} for $(H,H_0)=(H_1,T)$.
  By Duhamel's formula,
  $$
  \mathrm{e}^{-tH_1}-\mathrm{e}^{-tT} = \int_0^t \mathrm{e}^{-(t-s)H_1} V_\kappa \mathrm{e}^{-sT}\,ds.
  $$
  By \eqref{eq:massive-free-domination}, \eqref{eq:massive-H1-domination}, and \eqref{eq:Vkappa-absolute-bound},
  \begin{align}
    \label{eq:massive-Hardy-Duhamel-majorant}
    \left| (\mathrm{e}^{-tH_1}-\mathrm{e}^{-tT})(x,y) \right|
    \lesssim_t \int_0^t ds \int_{\mathbb{R}^d}dz\, \mathrm{e}^{-(t-s)L_\kappa}(x,z) |z|^{-\alpha} \mathrm{e}^{-sL_0}(z,y).
  \end{align}
  The kernel on the right-hand side is exactly the kernel majorant estimated in Subsections~\ref{s:compactness}--\ref{s:weightedbound}.
  Thus, Theorem~\ref{giere} applies and shows that
  \begin{align}
    \label{eq:massive-WH1T}
    W(H_1,T) = W(C_0(-\Delta)-V_\kappa,C_0(-\Delta))
  \end{align}
  exist and are asymptotically complete.

  \medskip
  \noindent
  {\bf Step 4: On $W(H_2,T)$.}
  We now verify the same two assumptions for $H_2$ and $T$. Since
  $$
  H_2=T-V_\kappa-V^S,
  $$
  Duhamel's formula yields
  \begin{align}
    \label{eq:massive-H2-Duhamel}
    \mathrm{e}^{-tH_2}-\mathrm{e}^{-tT}
    = \int_0^t \mathrm{e}^{-(t-s)H_2} (V_\kappa + V^S) \mathrm{e}^{-sT}\,ds.
  \end{align}
  By \eqref{eq:massive-H2-domination}, \eqref{eq:massive-free-domination}, and \eqref{eq:Vkappa-absolute-bound},
  \begin{align*}
    \left|\mathrm{e}^{-tH_2}-\mathrm{e}^{-tT}(x,y)\right|
    \lesssim_t \int_0^t ds \int_{\mathbb{R}^d}dz\, \mathrm{e}^{-(t-s)L_\kappa}(x,z)\left(|z|^{-\alpha} + |V^S(z)|\right)\mathrm{e}^{-sL_0}(z,y).
  \end{align*}
  The kernel on the right-hand side is exactly the kernel majorant estimated in Section~\ref{s:wlkappavlkappacomplete}.
  Thus, Theorem~\ref{giere} yields the asymptotic completeness of
  \begin{align}
    \label{eq:massive-WH2T}
    W(H_2,T) = W(C_0(-\Delta)-V_\kappa-V^S,C_0(-\Delta)).
  \end{align}

  \medskip
  \noindent
  {\bf Step 5: On $W(H_2,H_1)$.}
  By \eqref{eq:massive-WH1T} and \eqref{eq:massive-WH2T}, both $W(H_1,T)$ and $W(H_2,T)$ are asymptotically complete. Since $T$ has purely absolutely continuous spectrum, completeness gives $W(T,H_1) = W(H_1,T)^*$ on $\mathcal{H}_{\rm ac}(H_1)$. Hence, the chain rule yields also asymptotic completeness of $W(H_2,H_1)=W(C_0(-\Delta)-V_\kappa-V^S,C_0(-\Delta)-V_\kappa)$.

\label{lem:generalized-ishida-wada}
  Let $H_0=p(D)$ be a selfadjoint Fourier multiplier on $L^2(\mathbb{R}^d)$, where $p\in C^0(\mathbb{R}^d;[0,\infty))$.
  Let $U=U^{L}+U^{R}$ be real-valued potentials such that $H:=H_0-U$ has a selfadjoint realization.
  Assume that there exist
  $$
  0<\gamma\leq1,\qquad
  \varepsilon_{\rm s}\in\{-1,1\},\qquad
  c_0,C_0,R_0>0
  $$
  such that $U^{\rm L}\in L^\infty(\mathbb{R}^d)$ and
  \begin{align}
    \label{eq:IW-leading-lower}
    \varepsilon_{\rm s} U^{L}(x) & \geq c_0\langle x\rangle^{-\gamma}, \quad |x|\geq R_0, \\
    \label{eq:IW-leading-upper}
    |U^{L}(x)| & \leq C_0\langle x\rangle^{-\gamma}, \quad |x|\geq R_0.
  \end{align}
  Suppose moreover that there exists $0\not\equiv\varphi\in\mathcal S(\mathbb{R}^d)$ with $\hat\varphi\in C_c^\infty(\mathbb{R}^d)$ such that, with $K:=\operatorname{supp}\hat\varphi$, the function $p$ is $C^\infty$ on a neighborhood of $K$ and
  \begin{align}
    \label{eq:IW-nonzero-velocity}
    0< v_-:= \inf_{\xi\in K}|\nabla p(\xi)|
    \leq \sup_{\xi\in K}|\nabla p(\xi)| =: v_+
    <\infty.
  \end{align}
  Writing $\varphi_t:=\mathrm{e}^{-itH_0}\varphi$, assume that
  \begin{align}
    \label{eq:IW-remainder-small}
    \|U^{R}\varphi_t\|_2 = o(t^{-\gamma}), \quad t\to\infty.
  \end{align}
  Finally, assume that the Duhamel formula
  \begin{align}
    \label{eq:IW-Duhamel}
    \mathrm{e}^{it_2H}\mathrm{e}^{-it_2H_0}\varphi - \mathrm{e}^{it_1H}\mathrm{e}^{-it_1H_0}\varphi
    = -i \int_{t_1}^{t_2} \mathrm{e}^{itH}U\mathrm{e}^{-itH_0}\varphi\,dt
  \end{align}
  holds whenever $t_2>t_1$ are sufficiently large.
  Then $W(H,H_0):=\operatorname*{s-lim}_{t\to\infty}\mathrm{e}^{itH}\mathrm{e}^{-itH_0}$ does not exist.

  \smallskip
  In particular, if $p(\xi)=\Psi(|\xi|^2)$ is radial, $\Psi\in C^\infty(0,\infty)$, and $\Psi'(\lambda)>0$ for all $\lambda>0$, and if $U^{R}$ is supported in a fixed ball and, for some $0\leq a<d$,
  \begin{align}
    \label{eq:IW-local-singularity}
    |U^{R}(x)| \lesssim 1+|x|^{-a},
  \end{align}
  then one can choose a nonzero $\varphi$ with $\hat\varphi\in C_c^\infty(\mathbb{R}^d\setminus\{0\})$ such that \eqref{eq:IW-nonzero-velocity} and \eqref{eq:IW-remainder-small} hold. In fact, for every $N\in\mathbb{N}$, one has $\|U^{R}\varphi_t\|_2 \lesssim_N t^{-N}$.

We first prove the abstract statement. To this end, we argue by contradiction and assume that $W:=W(H,H_0)$ exists. Let $W_t:=\mathrm{e}^{itH}\mathrm{e}^{-itH_0}$.

  \medskip
  \noindent
  {\bf Step 1: Free propagation estimate.}
  Fix $0<a<v_-$. Since
  $$
  \varphi_t(x) = (2\pi)^{-d/2} \int_K \mathrm{e}^{i(x\cdot\xi-tp(\xi))} \hat\varphi(\xi)\,d\xi,
  $$
  we have, for $|x|\leq at$ and $\xi\in K$,
  $$
  \left| \nabla_\xi (x\cdot\xi-tp(\xi)) \right| \geq t(v_--a).
  $$
  Repeated integration by parts in $\xi$ therefore gives, for every $M\in\mathbb{N}$,
  $$
  \sup_{|x|\leq at} |\varphi_t(x)| \lesssim_{M,\varphi} t^{-M}.
  $$
  Thus, for every $N\in\mathbb{N}$,
  \begin{align}
    \label{eq:IW-inner-propagation}
    \left\| \mathbf{1}_{|x|\leq at}\varphi_t \right\|_2 \lesssim_{N,\varphi} t^{-N}.
  \end{align}
  Next, we show a crude propagation estimate. Since $x_j\mathrm{e}^{-itH_0} = \mathrm{e}^{-itH_0} (x_j+t\,\partial_jp(D))$,
  \begin{align}
    \label{eq:IW-first-moment}
    \|x\varphi_t\|_2 \leq \|x\varphi\|_2 + t\|\nabla p(D)\varphi\|_2 \lesssim_\varphi 1 + v_+ t.
  \end{align}
  We can choose $b=b_\varphi>a$ sufficiently large and then $T=T_\varphi>0$ sufficiently large, both depending on $\varphi$, so that
  \begin{align}
    \label{eq:IW-outer-mass}
    \left\| \mathbf{1}_{|x|\geq bt}\varphi_t \right\|_2^2
    \leq \frac{1}{b^2t^2} \|x\varphi_t\|_2^2
    \leq \frac14\|\varphi\|_2^2, \quad t\geq T
  \end{align}
  and                                                                          
  $$
  \left\| \mathbf{1}_{|x|\leq at}\varphi_t \right\|_2^2 \leq \frac14\|\varphi\|_2^2, \quad t\geq T.
  $$
  Thus, since $\|\varphi_t\|_2=\|\varphi\|_2$,
  \begin{align}
    \label{eq:IW-annulus-mass}
    \left\| \mathbf{1}_{at<|x|<bt}\varphi_t \right\|_2^2 \geq
    \frac12\|\varphi\|_2^2, \quad t \geq T.
  \end{align}


  \medskip
  \noindent
  {\bf Step 2: Lower bound for $\varepsilon_{\rm s}\langle\varphi_t,U\varphi_t\rangle$.}
  We take $t$ so large that $at\geq R_0$. By \eqref{eq:IW-leading-lower}, we may discard all contributions from $|x|\geq R_0$ outside the annulus in \eqref{eq:IW-annulus-mass} for a lower bound for $\varepsilon_{\rm s}\langle\varphi_t,U\varphi_t\rangle$. Hence,
  \begin{align}
    \label{eq:IW-leading-expectation-pre}
    \varepsilon_{\rm s} \langle \varphi_t,U^{L}\varphi_t\rangle
    \geq c_0 \int_{at<|x|<bt} \langle x\rangle^{-\gamma} |\varphi_t(x)|^2\,dx
    - \|U^{L}\|_\infty \left\| \mathbf{1}_{|x|<R_0}\varphi_t \right\|_2^2.
  \end{align}
  For the first term, we use $\langle x\rangle^{-\gamma} \gtrsim_b t^{-\gamma}$ and \eqref{eq:IW-annulus-mass}, and the last term in \eqref{eq:IW-leading-expectation-pre} is $\mathcal O_N(t^{-N})$ by \eqref{eq:IW-inner-propagation}. Therefore,
  \begin{align}
    \label{eq:IW-leading-expectation}
    \varepsilon_{\rm s} \langle \varphi_t, U^{L}\varphi_t\rangle
    \geq c_\varphi t^{-\gamma} - C_{N,\varphi}t^{-N}
  \end{align}
  for every $N$ and all sufficiently large $t$, where $c_\varphi>0$.

  By \eqref{eq:IW-remainder-small} and conservation of the $L^2$ norm,
  $$
  \left| \langle \varphi_t, U^{R}\varphi_t\rangle \right|
  \leq \|U^{R}\varphi_t\|_2\|\varphi\|_2
  = o(t^{-\gamma}).
  $$
  Hence, choosing $N>\gamma$,
  \begin{align}
    \label{eq:IW-total-expectation}
    \varepsilon_{\rm s} \langle \varphi_t, U\varphi_t\rangle \geq \frac{c_\varphi}{2}t^{-\gamma}
  \end{align}
  for all sufficiently large $t$.

  \medskip
  \noindent
  {\bf Step 3: Upper bound for $\|U\varphi_t\|_2$.}
  Using \eqref{eq:IW-leading-upper} and \eqref{eq:IW-inner-propagation}, we have, for $at\geq R_0$,
  \begin{align*}
    \|U^{L}\varphi_t\|_2
    & \leq \left\| U^{L} \mathbf{1}_{|x|<at}\varphi_t \right\|_2 + \left\| U^{L} \mathbf{1}_{|x|\geq at}\varphi_t \right\|_2 \\
    & \lesssim \|U^{L}\|_\infty \left\| \mathbf{1}_{|x|<at}\varphi_t \right\|_2 + t^{-\gamma}\|\varphi\|_2 \lesssim_\varphi t^{-\gamma}.
  \end{align*}
  Together with the assumption \eqref{eq:IW-remainder-small}, this yields
  \begin{align}
    \label{eq:IW-total-norm}
    \|U\varphi_t\|_2 \leq C_\varphi t^{-\gamma}
  \end{align}
  for all sufficiently large $t$.

  \medskip
  \noindent
  {\bf Step 4: Contradiction.}
  Since, by assumption, $W_t\varphi\to W\varphi$ in $L^2$, for every $\delta>0$ there exists $T_\delta$ such that
  \begin{align}
    \label{eq:IW-wave-convergence}
    \|(W-W_t)\varphi\|_2 \leq\delta, \quad t\geq T_\delta.
  \end{align}
  Let $t_2>t_1\geq T_\delta$. Then, by \eqref{eq:IW-Duhamel},
  \begin{align}
    \label{eq:IW-Duhamel-consequence}
    W_{t_2}\varphi-W_{t_1}\varphi = -i \int_{t_1}^{t_2} \mathrm{e}^{itH}U\varphi_t\,dt.
  \end{align}
  Since $\mathrm{e}^{-itH}W_t\varphi=\varphi_t$, we have $\mathrm{e}^{-itH}W\varphi = \varphi_t + \mathrm{e}^{-itH}(W-W_t)\varphi$. Therefore,
  \begin{align}
    \label{eq:IW-integrand-lower}
    \varepsilon_{\rm s} \operatorname{Re} \left\langle \mathrm{e}^{-itH}W\varphi, U\varphi_t \right\rangle
    \geq \varepsilon_{\rm s} \langle \varphi_t, U\varphi_t\rangle - \delta\|U\varphi_t\|_2, \quad t\geq T_\delta.
  \end{align}
  Choose $\delta>0$ so small that $\delta C_\varphi<\frac{c_\varphi}{4}$, where $C_\varphi$ is the constant in \eqref{eq:IW-total-norm}. Then \eqref{eq:IW-total-expectation}, \eqref{eq:IW-total-norm}, and \eqref{eq:IW-integrand-lower} imply
  $$
  \varepsilon_{\rm s} \operatorname{Re} \left\langle \mathrm{e}^{-itH}W\varphi,U\varphi_t \right\rangle
  \geq \frac{c_\varphi}{4}t^{-\gamma}, \quad t \text{ sufficiently large.}
  $$
  Taking the scalar product of the Duhamel formula \eqref{eq:IW-Duhamel-consequence} with $W\varphi$, multiplying by $i\varepsilon_{\rm s}$ and taking its real part, we obtain
  \begin{align}
    \label{eq:IW-final-lower}
    \left| \left\langle W\varphi, (W_{t_2}-W_{t_1})\varphi \right\rangle \right|
    \geq \frac{c_\varphi}{4} \int_{t_1}^{t_2}t^{-\gamma}\,dt.
  \end{align}
  Since $0<\gamma\leq1$, the right-hand side diverges as $t_2\to\infty$.
  On the other hand, $\left|\left\langle W\varphi,(W_{t_2}-W_{t_1})\varphi \right\rangle \right|
  \leq 2\|\varphi\|_2^2$, a contradiction. Thus, $W(H,H_0)$ does not exist.

  \medskip
  \noindent
  {\bf Step 5: Application.}
  Assume now
  $$
  p(\xi)=\Psi(|\xi|^2),
  \qquad
  \Psi\in C^\infty(0,\infty),
  \qquad
  \Psi'(\lambda)>0,
  \quad \lambda>0,
  $$
  and \eqref{eq:IW-local-singularity}, i.e., there is $R_1>0$ such that
  $$
  \operatorname{supp} U^{R}\subset B(0,R_1),
  \qquad
  |U^{R}(x)| \lesssim 1+|x|^{-a}, \qquad
  0\leq a<d.
  $$
  We now show the existence of a nonzero $\varphi$ with $\hat\varphi\in C_c^\infty(\mathbb{R}^d\setminus\{0\})$ such that \eqref{eq:IW-nonzero-velocity} and $\|U^{R}\varphi_t\|_2 = O_N(t^{-N})$ hold. To this end, choose $0<r_0<r_1<\infty$. Let $\ell\in\mathbb{N}_0$ satisfy
  \begin{align}
    \label{eq:IW-angular-condition}
    \ell>a-\frac d2,
  \end{align}
  choose $0\not\equiv g\in C_c^\infty((r_0,r_1))$, and let $Y_\ell$ be a spherical harmonic of degree $\ell$; in $d=1$, there are two spherical harmonics, $Y_0(x)=1$ and $Y_1(x)=x/|x|$ for $x\in\mathbb{R}$, and we take $\ell=1$ in this case. Take
  \begin{align}
    \label{eq:IW-angular-test-state}
    \hat\varphi(\xi) := g(|\xi|) Y_\ell\left(\frac{\xi}{|\xi|}\right).
  \end{align}
  Then, indeed, $\operatorname{supp}\hat\varphi \subset\subset\mathbb{R}^d\setminus\{0\}$ and $0\neq\varphi\in\mathcal S(\mathbb{R}^d)$.
  Since $\Psi'>0$, \eqref{eq:IW-nonzero-velocity} holds. Since $H_0$ is spherically symmetric, $\varphi_t$ remains in the same angular momentum channel $\ell$ for all $t$. Moreover, on the fixed ball $B(0,R_1)$, non-stationary phase gives, for every multi-index $\beta$ and every $N\in\mathbb{N}$,
  \begin{align}
    \label{eq:IW-local-derivative}
    \sup_{|x|\leq R_1} |\partial_x^\beta\varphi_t(x)| \lesssim_{\beta,N,\varphi} t^{-N}, \quad t\geq 2R_1/v_-.
  \end{align}
  For $|\beta|<\ell$, we have $\partial_x^\beta \varphi_t(0)=0$ as a consequence of
  \begin{align}
    \label{eq:IW-spherical-orthogonality}
    \int_{\mathbb{S}^{d-1}}\omega^\beta Y_\ell(\omega)\,d\omega=0.
  \end{align}
  To see this, recall that every homogeneous polynomial $p$ on $\mathbb{R}^d$ of degree $m$ can be uniquely written in the form
  $$
  p = p_m + |x|^2p_{m-2} + ... + |x|^{2k}p_{m-2k},
  $$
  where $k=\lfloor m/2\rfloor$ and each $p_j$ is a harmonic, homogeneous polynomial of degree $j$; see \cite[Theorem~5.7]{Axleretal2001}. Restricting this equality to $\mathbb{S}^{d-1}$ allows us to write
  $$
  \omega^\beta = Y_{|\beta|}(\omega) + Y_{|\beta|-2}(\omega)+ ...
  $$
  This expansion, $|\beta|<\ell$, and the orthonormality of spherical harmonics yield \eqref{eq:IW-spherical-orthogonality}.

  Taylor's theorem and \eqref{eq:IW-local-derivative} thus give
  \begin{align}
    \label{eq:IW-origin-vanishing}
    |\varphi_t(x)| \lesssim_{N,\varphi} t^{-N}|x|^\ell, \quad |x|\leq R_1, \ t\geq2R_1/v_-.
  \end{align}
  Hence,
  \begin{align}
    \label{eq:IW-local-remainder}
    \|U^{R}\varphi_t\|_2^2
    \lesssim_{N,\varphi} t^{-2N} \int_{|x|\leq R_1} (1+|x|^{-2a})|x|^{2\ell}\,dx
    \lesssim_{N,\varphi} t^{-2N}, \quad t\geq2R_1/v_-,
  \end{align}
  where the integral is finite since $2\ell-2a+d>0$. This concludes the proof.

We write
  $$
  L:=L_\kappa,
  \qquad
  H:=L_\kappa-V^L,
  \qquad
  \rho:=\rho_L,
  $$
  and argue by contradiction. Thus, suppose that $W:=W(H,L) = \operatorname*{s-lim}_{t\to\infty}\mathrm{e}^{i t H}\mathrm{e}^{-i t L}$
  exists.

  \medskip
  \noindent
  {\bf Step 1: Constructing a test function.}
  Since $\kappa<\kappa_{\rm c}$, the spectrum of $L_\kappa$ is $[0,\infty)$ and is purely absolutely continuous. Choose $0\not\equiv h\in C_c^\infty(0,\infty)$ such that $h(L)\neq0$. Since $\mathcal{D}(\langle x\rangle)\cap\mathcal{D}(\langle A\rangle^2)$ is dense in $L^2(\mathbb{R}^d)$, we can choose
  $$
  \psi\in \mathcal{D}(\langle x\rangle)\cap\mathcal{D}(\langle A\rangle^2)
  $$
  such that
  $$
  \varphi:=h(L)\psi\neq0.
  $$
  By Lemma~\ref{lem9-small-alpha}, respectively by Lemma~\ref{lem9} when $\alpha=1$, evaluated at $t=0$ and $\mu=1$, we have $h(L)\mathcal{D}(\langle x\rangle) \subset \mathcal{D}(\langle x\rangle)$. Moreover, by $\mathrm{e}^{i s A}L\mathrm{e}^{-i s A} = \mathrm{e}^{-\alpha s}L$,
  $$
  \mathrm{e}^{i s A}h(L)\mathrm{e}^{-i s A} = h(\mathrm{e}^{-\alpha s}L).
  $$
  Since $h\in C_c^\infty(0,\infty)$, the right-hand side is $C^\infty$ in $s$ in operator norm. Hence, $h(L)\in C^\infty(A)$ and, in particular, $h(L)\mathcal{D}(\langle A\rangle^2) \subset \mathcal{D}(\langle A\rangle^2)$. Thus, $\varphi\in \mathcal{D}(\langle x\rangle)\cap\mathcal{D}(\langle A\rangle^2)$. Choose $f\in C_c^\infty(0,\infty)$ such that $f=1$ on a neighborhood of $\operatorname{supp} h$. Then
  \begin{align}
    \label{eq:nonexistence-unified-spectral-localization}
    \varphi=f(L)\varphi.
  \end{align}
  In particular, $\varphi\in\mathcal{D}(L^m)$ for every $m\geq0$. We now set $u_t:=\mathrm{e}^{-i t L}\varphi$.

  \medskip
  \noindent
  {\bf Step 2: Duhamel decomposition.}
  Since $V^L$ is bounded,
  $$
  \frac{d}{dt} \left( \mathrm{e}^{i t H}\mathrm{e}^{-i t L} \right) = -i\mathrm{e}^{i t H}V^L\mathrm{e}^{-i t L}
  $$
  in the strong sense. Therefore, for $0<t_1<t_2$,
  \begin{align}
    \label{eq:nonexistence-unified-Duhamel}
    \left\langle W\varphi, \left(\mathrm{e}^{i t_2 H}\mathrm{e}^{-i t_2 L} - \mathrm{e}^{i t_1 H}\mathrm{e}^{-i t_1 L} \right)\varphi \right\rangle 
    = -i\int_{t_1}^{t_2} \left\langle W\varphi, \mathrm{e}^{i t H}V^Lu_t \right\rangle\,dt.
  \end{align}
  For some $\eta>0$ to be specified below (in Step~3), we choose $\lambda>0$ so large that
  \begin{align}
    \label{eq:nonexistence-unified-positive-resolvent}
    \lambda+H\geq\eta>0.
  \end{align}
  By the intertwining property, $(\lambda+H)W\varphi = W(\lambda+L)\varphi$. Writing $R_\lambda:=(\lambda+H)^{-1}$, we get
  \begin{align}
    \label{eq:nonexistence-unified-resolvent-split}
    \begin{split}
      \left\langle W\varphi,\mathrm{e}^{i t H}V^Lu_t \right\rangle
      & = \left\langle \mathrm{e}^{-i t H}W(\lambda+L)\varphi,R_\lambda V^L u_t \right\rangle \\
      & = \left\langle \mathrm{e}^{-i t L}(\lambda+L)\varphi, R_\lambda V^Lu_t \right\rangle \\
      & \quad + \left\langle \mathrm{e}^{-i t H} \left(W-\mathrm{e}^{i t H}\mathrm{e}^{-i t L} \right)(\lambda+L)\varphi, R_\lambda V^Lu_t \right\rangle.
    \end{split}
  \end{align}
  Define
  \begin{align}
    \label{eq:nonexistence-unified-J1}
    J_1 & := \int_{t_1}^{t_2} \left\langle \mathrm{e}^{-i t L}(\lambda+L)\varphi, R_\lambda V^Lu_t \right\rangle\,dt, \\
    \label{eq:nonexistence-unified-J2}
    J_2 & := \int_{t_1}^{t_2}\left\langle \mathrm{e}^{-i t H} \left( W-\mathrm{e}^{i t H}\mathrm{e}^{-i t L} \right)(\lambda+L)\varphi, R_\lambda V^Lu_t \right\rangle\,dt.
  \end{align}
  Then,
  \begin{align}
    \label{eq:nonexistence-unified-J1J2}
    \left\langle W\varphi, \left(\mathrm{e}^{i t_2 H}\mathrm{e}^{-i t_2 L} - \mathrm{e}^{i t_1 H}\mathrm{e}^{-i t_1 L} \right)\varphi \right\rangle
    = -i (J_1 + J_2).
  \end{align}

  \medskip
  \noindent
  {\bf Step 3: Lower bound for the main term $J_1$.}
  Since $\mathrm{e}^{-i t L}(\lambda+L)\varphi = (\lambda+L)u_t$ and $R_\lambda V^Lu_t\in\mathcal{D}(H)=\mathcal{D}(L)$,
  $$
  q(t)
  := \left\langle (\lambda+L)u_t, R_\lambda V^Lu_t \right\rangle
  = \left\langle u_t, (\lambda+L)R_\lambda V^Lu_t \right\rangle
  $$
  is well-defined.
  Since $L=H+V^L$, we have $(\lambda+L)R_\lambda = 1+V^LR_\lambda$. Hence,
  \begin{align}
    \label{eq:nonexistence-unified-q}
    q(t) = \langle u_t, V^Lu_t \rangle + \langle V^Lu_t, R_\lambda V^Lu_t \rangle.
  \end{align}
  Suppose first that $V^L$ satisfies \eqref{ass1}, i.e., is positive. Since $R_\lambda\geq0$,
  \begin{align}
    \label{eq:nonexistence-unified-q-positive}
    q(t) \geq K_1 \left\langle u_t, \langle x\rangle^{-\rho}u_t \right\rangle.
  \end{align}
  Suppose instead that $V^L$ satisfies \eqref{ass2}, i.e., is negative. In this case, choose $\eta$ (and hence $\lambda$) in~\eqref{eq:nonexistence-unified-positive-resolvent} so large that $\eta>K_2^2/K_1$. Then, $0<R_\lambda\leq\eta^{-1}$. Since $|V^L|^2 \leq K_2^2\langle x\rangle^{-\rho}$,
  \begin{align}
    \label{eq:nonexistence-unified-q-negative}
    \begin{split}
      q(t)
      & \leq -K_1 \left\langle u_t, \langle x\rangle^{-\rho} u_t \right\rangle + \eta^{-1} \langle u_t, |V^L|^2 u_t\rangle \\
      & \leq -\left(K_1-\frac{K_2^2}{\eta} \right)\left\langle u_t, \langle x\rangle^{-\rho} u_t \right\rangle.
    \end{split}
  \end{align}
  Thus, in either case, $q(t)$ has a fixed sign, independent of $t$, and there exists $c_0>0$ such that
  \begin{align}
    \label{eq:nonexistence-unified-q-lower}
    |q(t)| \geq c_0 \left\langle u_t, \langle x\rangle^{-\rho} u_t\right\rangle.
  \end{align}
  We now show that a fixed positive fraction of the mass of $u_t$ stays inside a ballistic cone. By \eqref{eq:nonexistence-unified-spectral-localization} and Lemma~\ref{lem9-small-alpha}, respectively Lemma~\ref{lem9} when $\alpha=1$, we have, for $t\geq1$, that $\|\langle x\rangle u_t\| \lesssim_f t\|\langle x\rangle\varphi\|$. Therefore, for every $\Theta>0$,
  \begin{align}
    \label{eq:nonexistence-unified-outer-cone}
    \left\| \mathbf{1}_{|x|\geq\Theta t}u_t \right\|
    \leq \frac{1}{\Theta t} \|\langle x\rangle u_t\|
    \lesssim_f \Theta^{-1}\|\langle x\rangle\varphi\|.
  \end{align}
  Choose $\Theta=\Theta_\varphi\geq1$ so large that
  $$
  \left\| \mathbf{1}_{|x|\geq\Theta t}u_t \right\|^2 \leq \frac12\|\varphi\|^2
  $$
  for every $t\geq1$. Since $\|u_t\|=\|\varphi\|$, we then have
  \begin{align}
    \label{eq:nonexistence-unified-inner-mass}
    \left\| \mathbf{1}_{|x|<\Theta t}u_t\right\|^2 \geq \frac12\|\varphi\|^2.
  \end{align}
  On $\{|x|<\Theta t\}$, with $t\geq1$ and $\Theta\geq1$, we have $\langle x\rangle \leq \sqrt{1+\Theta^2t^2} \leq \sqrt2\,\Theta t$. Hence,
  $$
  \langle x\rangle^{-\rho} \geq (\sqrt2\,\Theta)^{-\rho}t^{-\rho} \quad \text{on } \{|x|<\Theta t\}.
  $$
  By \eqref{eq:nonexistence-unified-q-lower} and \eqref{eq:nonexistence-unified-inner-mass}, there exists $c_\varphi>0$ such that
  \begin{align}
    \label{eq:nonexistence-unified-q-final}
    |q(t)| \geq c_\varphi t^{-\rho}, \quad t\geq1.
  \end{align}
  Since $q(t)$ has a fixed sign,
  \begin{align}
    \label{eq:nonexistence-unified-J1-lower}
    |J_1| = \int_{t_1}^{t_2}|q(t)|\,dt \geq c_\varphi \int_{t_1}^{t_2}t^{-\rho}\,dt
  \end{align}
  whenever $t_1\geq1$.

  \medskip
  \noindent
  {\bf Step 4: Estimate of the error term $J_2$.}
  Let $\varepsilon>0$. Since, by assumption, $\mathrm{e}^{i t H}\mathrm{e}^{-i t L} \to W$ strongly, there exists $T_\varepsilon\geq1$ such that
  \begin{align}
    \label{eq:nonexistence-unified-wave-convergence}
    \left\| \left(W-\mathrm{e}^{i t H}\mathrm{e}^{-i t L}\right)(\lambda+L)\varphi \right\| \leq\varepsilon
  \end{align}
  for all $t\geq T_\varepsilon$. Thus, if $t_1\geq T_\varepsilon$,
  \begin{align}
    \label{eq:nonexistence-unified-J2-first}
    |J_2| \leq \varepsilon \int_{t_1}^{t_2}\|R_\lambda V^Lu_t\|\,dt.
  \end{align}
  We now estimate $R_\lambda V^Lu_t$. To this end, let $\theta>0$ be the minimal escape velocity constant from Theorem~\ref{the6} with $V=0$, the function $f$ from \eqref{eq:nonexistence-unified-spectral-localization}, and $\nu=2$ there. Choose $\chi\in C^\infty(\mathbb{R};[0,1])$ such that
  $$
  \chi(s)=0
  \quad\text{for }s\leq\frac{\theta}{2},
  \qquad
  \chi(s)=1
  \quad\text{for }s\geq\theta.
  $$
  We decompose
  \begin{align}
    \label{eq:nonexistence-unified-low-high-A}
    \|R_\lambda V^Lu_t\|
    \leq \|R_\lambda V^L(1-\chi(A/t))u_t\| + \|R_\lambda V^L\chi(A/t)u_t\|.
  \end{align}
  Since $|1-\chi(s)| \leq \mathbf{1}_{(-\infty,\theta]}(s)$, Theorem~\ref{the6} and \eqref{eq:nonexistence-unified-spectral-localization} yield, for all sufficiently large $t$,
  \begin{align}
    \label{eq:nonexistence-unified-low-A}
    \|R_\lambda V^L(1-\chi(A/t))u_t\|
    \lesssim \left\| \mathbf{1}\left(\frac At\leq\theta\right) f(L)\mathrm{e}^{-i t L}\varphi \right\|
    \lesssim t^{-2}\|\langle A\rangle^2\varphi\|.
  \end{align}
  We next estimate the high-$A/t$ contribution. By Lemma~\ref{lem:commutators-spectral-cutoff},
  \begin{align}
    \label{eq:nonexistence-unified-cutoff-commutators}
    \|[\chi(A/t),V^L]\| + \|[\chi(A/t),R_\lambda]\| \lesssim_{V,\eta} t^{-1}.
  \end{align}
  Therefore,
  \begin{align}
    \label{eq:nonexistence-unified-move-chi}
    R_\lambda V^L\chi(A/t) = \chi(A/t)R_\lambda V^L + E_t,
    \qquad
    \|E_t\|\lesssim_{V,\eta} t^{-1}.
  \end{align}
  We claim that
  \begin{align}
    \label{eq:nonexistence-unified-A-regularity}
    \langle A\rangle^\rho R_\lambda V^Lf(L) \in\mathcal B(L^2).
  \end{align}
  If $0<\rho<1$, this is Corollary~\ref{cor:fractional-A-resolvent-V} since $\rho\leq\alpha$.
  It remains to prove \eqref{eq:nonexistence-unified-A-regularity} for $\rho=1$, i.e., $\alpha=1$ in the present parameter range. To this end, we use $A = -i\left(x\cdot\nabla+\frac d2\right)$ to get
  $$
  AV^L =-i\sum_{j=1}^d x_jV^L\partial_j - i\left(x\cdot\nabla V^L+\frac d2V^L \right).
  $$
  By \eqref{ass5} with $\rho=1$, we have $x_jV^L\in W^{1,\infty}(\mathbb{R}^d)$ and $x\cdot\nabla V^L,\, V^L\in L^\infty(\mathbb{R}^d)$. Hence,
  \begin{align}
    \label{eq:nonexistence-unified-AV-sandwich}
    \langle D\rangle^{-1/2} AV^L\langle D\rangle^{-1/2} \in\mathcal B(L^2),
  \end{align}
  because $\xi_j\langle\xi\rangle^{-1} \in L^\infty(\mathbb{R}^d)$ and multiplication by $W^{1,\infty}$ functions is bounded on $H^{1/2}(\mathbb{R}^d)$. Since $\kappa<\kappa_{\rm c}$, we have that $R_\lambda\langle D\rangle^{1/2}$ and $\langle D\rangle^{1/2}f(L)$ are bounded for $\alpha=1$. Thus,
  \begin{align*}
    R_\lambda AV^Lf(L)
    & = R_\lambda\langle D\rangle^{1/2} \left( \langle D\rangle^{-1/2} AV^L \langle D\rangle^{-1/2}\right) \langle D\rangle^{1/2}f(L) \in \mathcal B(L^2).
  \end{align*}
  Since
  $$
  AR_\lambda V^Lf(L) = R_\lambda AV^Lf(L) + [A,R_\lambda]V^Lf(L),
  $$
  and $[A,R_\lambda]\in\mathcal B(L^2)$ by Lemma~\ref{lem:commutators-spectral-cutoff}, we obtain $AR_\lambda V^Lf(L)\in\mathcal B(L^2)$. Hence, we have shown $\langle A\rangle R_\lambda V^Lf(L)\in\mathcal B(L^2)$, i.e., \eqref{eq:nonexistence-unified-A-regularity} also holds for $\rho=\alpha=1$.

  Since $\chi(A/t)$ is supported where $A/t\geq\theta/2$,
  \begin{align}
    \label{eq:nonexistence-unified-chi-A-weight}
    \|\chi(A/t)\langle A\rangle^{-\rho}\|
    \lesssim_{\theta,\rho} t^{-\rho}, \quad t\geq1.
  \end{align}
  Using $u_t=f(L)u_t$, we obtain from \eqref{eq:nonexistence-unified-A-regularity} and \eqref{eq:nonexistence-unified-chi-A-weight} that
  \begin{align}
    \label{eq:nonexistence-unified-high-A-main}
    \|\chi(A/t)R_\lambda V^Lu_t\| \lesssim t^{-\rho}\|\varphi\|.
  \end{align}
  Combining this with \eqref{eq:nonexistence-unified-move-chi}, and using $0<\rho\leq1$, gives
  \begin{align}
    \label{eq:nonexistence-unified-high-A}
    \|R_\lambda V^L\chi(A/t)u_t\| \lesssim_\varphi t^{-\rho}.
  \end{align}

  Together with \eqref{eq:nonexistence-unified-low-A}, we conclude
  \begin{align}
    \label{eq:nonexistence-unified-RV-bound}
    \|R_\lambda V^Lu_t\| \lesssim_\varphi t^{-2}+t^{-\rho} \quad \text{for $t$ large enough.}
  \end{align}
  Thus,
  \begin{align}
    \label{eq:nonexistence-unified-J2-final}
    |J_2| \leq \varepsilon C_\varphi \left(1+\int_{t_1}^{t_2}t^{-\rho}\,dt\right),
  \end{align}
  where $C_\varphi$ is independent of $\varepsilon,t_1,t_2$.

  \medskip
  \noindent
  {\bf Step 5: Contradiction.}
  Combining \eqref{eq:nonexistence-unified-J1-lower} and \eqref{eq:nonexistence-unified-J2-final}, we obtain
  \begin{align}
    \label{eq:nonexistence-unified-final-lower}
    |J_1|-|J_2| \geq \left(c_\varphi-\varepsilon C_\varphi\right) \int_{t_1}^{t_2}t^{-\rho}\,dt - \varepsilon C_\varphi.
  \end{align}
  Choose $\varepsilon>0$ sufficiently small that $c_\varphi-\varepsilon C_\varphi>0$, and then choose $t_1\geq T_\varepsilon$ sufficiently large that all preceding propagation estimates apply. Since
$0<\rho\leq1$, we have
  $$
  \int_{t_1}^{t_2}t^{-\rho}\,dt \to \infty \quad \text{as }t_2\to\infty.
  $$
  Hence,
  \begin{align}
    \label{eq:nonexistence-unified-divergence}
    |J_1|-|J_2|\to \infty.
  \end{align}
  On the other hand, by \eqref{eq:nonexistence-unified-J1J2} and the triangle inequality,
  \begin{align}
    \label{eq:nonexistence-unified-upper}
    |J_1|-|J_2|
    \leq |J_1+J_2|
    = \left| \left\langle W\varphi, \left(\mathrm{e}^{i t_2 H}\mathrm{e}^{-i t_2 L} - \mathrm{e}^{i t_1 H}\mathrm{e}^{-i t_1 L} \right)\varphi \right\rangle \right|
    \leq 2\|\varphi\|^2
  \end{align}
  since $\mathrm{e}^{i t H}\mathrm{e}^{-i t L}$ is unitary and $W$ is an isometry. This contradicts \eqref{eq:nonexistence-unified-divergence}. Thus, $W(L_\kappa-V^L,L_\kappa)$ does not exist.

\label{heatkernelestimates-halfplane}
  Let $d\in\mathbb{N}$, $\alpha\in(0,2]\cap(0,d)$, $\tilde\kappa\leq\kappa\leq\kappa_{\rm c}$, and $\sigma=\Phi^{-1}(\kappa)\in(-M,(d-\alpha)/2]$.
  Assume $V:\mathbb{R}^d\to\mathbb{R}$ obeys $\tilde\kappa/|x|^\alpha \leq V(x)\leq\kappa/|x|^\alpha$ for all $x\in\mathbb{R}^d$. Let $H=(-\Delta)^{\alpha/2}-V$.  
  Let $p_z(x,y)$ be the kernel associated to the semigroups $\mathrm{e}^{-zH}$ with $z\in \mathbb{C}_{\pi/2}=\{z\in \mathbb{C}: |\arg z|<\pi/2\}$.
  \begin{enumerate}
  \item Let $\alpha\in (0,2)$. Then for any $\varepsilon\in (0,1)$, there exists a constant $C=C_\varepsilon$ such that
    \begin{align}
      \label{boundedp_t(x,y)-complex-alpha < 2}
      |p_z(x,y)| \leq C \left(1\wedge\frac{|x|}{|z|^{1/\alpha}}\right)^{-\sigma} \left(1\wedge\frac{|y|}{|z|^{1/\alpha}}\right)^{-\sigma} |z|^{-d/\alpha}\left(\frac{|z|^{1/\alpha}}{|z|^{1/\alpha}+|x-y|}\right)^{(d+\alpha)(1-\varepsilon)}
    \end{align}
    for all $x,y \in \mathbb{R}^d$ and $z\in \mathbb{C}_{\varepsilon\pi/4}$.

    \item Let $\alpha=2$. Then there exist constants $C, c>0$ such that
    \begin{align}
      \label{boundedp_t(x,y)-complex-alpha = 2}
      |p_z(x,y)|\leq C  \left(1\wedge\frac{|x|}{\sqrt{|z|}}\right)^{-\sigma} \left(1\wedge\frac{|y|}{\sqrt{|z|}}\right)^{-\sigma}|z|^{-d/2} \exp\left(-\frac{|x-y|^2}{c|z|}\right)
    \end{align}
    for all $x,y \in {\mathbb{R}^d}$ and $z\in \mathbb{C}_{\pi/4}$.
  \end{enumerate}

We only give the proof for \eqref{boundedp_t(x,y)-complex-alpha < 2} since the proof of  \eqref{boundedp_t(x,y)-complex-alpha = 2} is similar. To that end, we use a Phragm\'en--Lindel\"of argument as in \cite[Section~3.4]{Davies1990}. We set
  \[
    w_z(x)= \left(1+\frac{ {|z|^{1/\alpha}}}{|x|}\right)^{-\sigma}, \quad x\in  \mathbb{R}^d,\ z\in\mathbb{C}
  \]
  and first claim that there exists $C>0$ such that
  \begin{align}\label{boundedp_t(x,y)-complex1'}
    \left|w_z(x) p_z(x,y)w_z(y)\right|\le \frac{C}{|z|^{d/\alpha}}
  \end{align}
  holds for all $x,y\in \mathbb{R}^d$ and $z\in\mathbb{C}_{\pi/4}$.
  To prove this, we define, for $f: \mathbb{R}^d \rightarrow \mathbb{C}$, the norms
  $$
  |f|_{L_{w_{z}}^\infty(\mathbb{R}^d)} = \sup_{x\in \mathbb{R}^d} \left|f(x)w_z(x)\right|
  $$
  and
  \[
    |f|_{L_{w_{z}}^1(\mathbb{R}^d)} = \int_{{\mathbb{R}^d}}|f(x)|w_z(x)dx.
  \]
  Hence, the inequality  (\ref{boundedp_t(x,y)-complex1'}) is equivalent to
  $$
  \|\mathrm{e}^{-zH}\|_{L^1_{w_z^{-1}}(\mathbb{R}^d)\rightarrow L^\infty_{w_z}(\mathbb{R}^d)} \leq \frac{C}{|z|^{d/\alpha}}.
  $$
  For $z\in\mathbb{C}_{\pi/4}$ we can write $z=2t+is$ for some $t\geq 0$ and $s\in \mathbb{R}$ such that $t\sim |z|$. Then, 
  \begin{align*}
    & \|\mathrm{e}^{-z H}\|_{L^1_{w_z^{-1}}(\mathbb{R}^d)\rightarrow L^\infty_{w_z}(\mathbb{R}^d)} \\
    & \quad \le \|\mathrm{e}^{-tH}\|_{L^2(\mathbb{R}^d)\rightarrow L^\infty_{w_z}(\mathbb{R}^d)} \|\mathrm{e}^{-isH}\|_{L^2(\mathbb{R}^d)\rightarrow L^2(\mathbb{R}^d)} \|\mathrm{e}^{-tH}\|_{L^1_{{w_z}^{-1}}({\mathbb{R}^d})\rightarrow L^2({\mathbb{R}^d})}.
  \end{align*}
  We first estimate $\|\mathrm{e}^{-tH}\|_{L^1_{{w_z}^{-1}}({\mathbb{R}^d})\rightarrow L^2({\mathbb{R}^d})}$. For $f\in L^1_{{w_z}^{-1}}({\mathbb{R}^d})$, we have, by the real-time heat kernel estimates for $L_\kappa$, Trotter's formula, and
  $$
  \left(1\wedge\frac{|y|}{t^{1/\alpha}}\right)^{-\sigma}
  \sim \left(1\wedge\frac{|y|}{|z|^{1/\alpha}}\right)^{-\sigma}
  \sim w_z(y)^{-1},
  $$
  that
  \begin{align*}
    \footnotesize
    \begin{split}
      \|\mathrm{e}^{-tH}f\|_{L^2({\mathbb{R}^d})}
      & \leq \|\mathrm{e}^{-tL_\kappa}|f|\|_{L^2({\mathbb{R}^d})} \\
      & \lesssim \left[\int_{\mathbb{R}^d} \left|\int_{\mathbb{R}^d} {t^{-\frac d\alpha}  \left( \frac{t^{1/\alpha}+|x-y|}{t^{1/\alpha}}\right)^{-d-\alpha} w_z(y)^{-1} |f(y)|}\,dy \right|^2 \left(1\wedge\frac{|x|}{t^{1/\alpha}}\right)^{-2\sigma} \,dx\right]^{\frac12}.
    \end{split}
  \end{align*}
  By Minkowski's inequality,
  \begin{align*}
    \footnotesize
    \begin{split}
    \|\mathrm{e}^{-tH}f\|_{L^2({\mathbb{R}^d})}
    & \lesssim \int_{\mathbb{R}^d}\left[\int_{\mathbb{R}^d}\left| t^{-\frac d\alpha} \left(\frac{t^{1/\alpha}+|x-y|}{t^{1/\alpha}}\right)^{-d-\alpha}\right|^2 \left(1\wedge\frac{|x|}{t^{1/\alpha}}\right)^{-2\sigma}\,dx\right]^{\frac12} w_z(y)^{-1}|f(y)|\,dy \\
    & \lesssim  {\sup_{y\in {\mathbb{R}^d}}}\left[\int_{\mathbb{R}^d}\left| t^{-\frac d\alpha}\left(\frac{t^{1/\alpha}+|x-y|}{t^{1/\alpha}}\right)^{-d-\alpha}\right|^2 \left(1\wedge\frac{|x|}{t^{1/\alpha}}\right)^{-2\sigma}\,dx\right]^{\frac12} \|f\|_{L^1_{w_z^{-1}}}.
    \end{split}
  \end{align*}
  This, along with the fact that
  \begin{align}
    \label{eq1-norm}
    {\sup_{y\in {\mathbb{R}^d}}} \left[\int_{\mathbb{R}^d}\left| t^{-d/\alpha} \left(\frac{t^{1/\alpha}+|x-y|}{t^{1/\alpha}}\right)^{-d-\alpha}\right|^2 \left(1\wedge\frac{|x|}{t^{1/\alpha}}\right)^{-2\sigma}\, dx\right]^{1/2}
    \lesssim t^{-\frac{d}{2\alpha}},
  \end{align}
  which can be seen by distinguishing between $|x|\lessgtr t^{1/\alpha}$ and using $\sigma<d/2$, implies
  \[
    \|\mathrm{e}^{-tH}f\|_{L^2({\mathbb{R}^d})} \lesssim t^{-\frac{d}{2\alpha}}\|f\|_{L^1_{w_z^{-1}}(\mathbb{R}^d)}.
  \]
  It follows that 
  \[
    \|\mathrm{e}^{-tH}\|_{L^1_{{w_z}^{-1}}({\mathbb{R}^d})\rightarrow L^2({\mathbb{R}^d})} \lesssim t^{-\frac{d}{2\alpha}}.
  \]
  Similarly,
  \[
    \|\mathrm{e}^{-tH}\|_{L^2({\mathbb{R}^d})\to L^\infty_{{w_z}}({\mathbb{R}^d})} \lesssim t^{-\frac{d}{2\alpha}}.
  \]
  Moreover, since $H$ is a (nonnegative) selfadjoint operator, $\|\mathrm{e}^{-isH}\|_{L^2({\mathbb{R}^d})\rightarrow L^2({\mathbb{R}^d})}\leq 1$. Taking these three estimates into account, we get
  $$
  \|\mathrm{e}^{-zH}\|_{L^1_{w_z^{-1}}({\mathbb{R}^d})\rightarrow L^\infty_{w_z}({\mathbb{R}^d})}
  \le t^{-\frac{d}{\alpha}}
  \sim \frac{1}{|z|^{d/\alpha}},
  $$
  which implies \eqref{boundedp_t(x,y)-complex1'}, i.e.,
  \[
    |p_z(x,y)| \lesssim \frac{1}{|z|^{d/\alpha}} \left(1\wedge\frac{|x|}{|z|^{1/\alpha}}\right)^{-\sigma}\left(1\wedge\frac{|y|}{|z|^{1/\alpha}}\right)^{-\sigma}
  \]
  for all $x,y\in {\mathbb{R}^d}$ and $z\in\mathbb{C}_{\pi/4}$. By the Phragm\'en--Lindel\"of theorem in \cite[Proposition 3.3]{DuongRobinson1996} or \cite[Theorem~2.1]{Merz2022}, we get \eqref{boundedp_t(x,y)-complex-alpha < 2}.

\label{thm-ptk}
  Let $d\in\mathbb{N}$, $\alpha\in(0,2]\cap(0,d)$, $\tilde\kappa\leq\kappa\leq\kappa_{\rm c}$, and $\sigma=\Phi^{-1}(\kappa)\in(-M,(d-\alpha)/2]$.
  Assume $V:\mathbb{R}^d\to\mathbb{R}$ obeys $\tilde\kappa/|x|^\alpha \leq V(x)\leq\kappa/|x|^\alpha$ for all $x\in\mathbb{R}^d$. Let $H=(-\Delta)^{\alpha/2}-V$.
  For each $k\in \mathbb{N}$, we denote by $p_{t,k}(x,y)$ the kernel of $H^k \mathrm{e}^{-tH}$.
  \begin{enumerate}
  \item Let $\alpha\in (0,2)$. Then for any $\varepsilon>0$ and $k\in \mathbb{N}$, there exists a constant $C=C(k,\varepsilon)$ such that
    \begin{align}
      \label{boundedp_t k(x,y)-complex-alpha < 2}
      |p_{t,k}(x,y)|\le C  \left(1\wedge\frac{|x|}{t^{1/\alpha}}\right)^{-\sigma} \left(1\wedge\frac{|y|}{t^{1/\alpha}}\right)^{-\sigma} t^{-(k+d/\alpha)} \left(\frac{t^{1/\alpha}+|x-y|}{t^{1/\alpha}}\right)^{-d-\alpha+\varepsilon}
    \end{align}
    for all $x,y \in {\mathbb{R}^d}$ and $t>0$.

  \item Let $\alpha=2$. Then for each $k\in \mathbb{N}$ there exist constants $C, c>0$ such that
    \begin{align}
      \label{boundedp_t k(x,y)-complex-alpha = 2}
      |p_{t,k}(x,y)| \le C \left(1\wedge\frac{|x|}{\sqrt t}\right)^{-\sigma} \left(1\wedge\frac{|y|}{\sqrt t}\right)^{-\sigma} t^{-(k+d/2)}\exp\left(-\frac{|x-y|^2}{ct}\right)
    \end{align}
    for all $x,y \in {\mathbb{R}^d}$ and $t>0$.
  \end{enumerate}
